// One line per item so that branches merge; tests/pathindex.test.ts fails when it is stale (run npm run manifest).
import type { Quiz } from '../chapters/types';

export const RECAPS: Record<string, Quiz[]> = {
  "basics": [{"question":"Four lamps show 1101 (the leftmost worth 8). What number is that?","options":["13","11","1101","14"],"answer":0,"explain":"8 + 4 + 0 + 1 = 13.","why":["Right: 8 + 4 + 1.","11 is 1011: the two middle lamps are swapped.","That is the pattern read as a decimal number.","14 is 1110."]},{"question":"A switch on the return wire of a lamp's loop is opened. What happens?","options":["The lamp goes out: the loop is broken","The lamp stays lit: the return wire is only ground","The lamp dims to half","The battery's voltage drops to 0"],"answer":0,"explain":"Current needs the whole loop. Breaking it anywhere stops it everywhere.","why":["Right.","Ground is still part of the loop; current must come back through it.","Dimming needs a second resistance in the loop, not a break.","The battery still holds its voltage; no current flows, so nothing is used."]},{"question":"Why does a computer read each wire as two levels rather than ten?","options":["Two levels tolerate far more noise, and can be restored at every step","Ten levels cannot be made with transistors","Binary arithmetic is the only kind that works","Two levels carry more information per wire"],"answer":0,"explain":"Halfway between two levels is a wide margin; between ten it is a narrow one.","why":["Right.","Multi-level circuits exist (flash memory stores 2 to 4 bits a cell); they need careful, slow reading.","Arithmetic works in any base; binary is chosen for the wires.","Ten levels carry more per symbol, about 3.3 bits, which is exactly what they pay for in noise margin."]}],
  "relays": [{"question":"A relay is operated. Its 24 V supply sags to 10 V. What does it do?","options":["It stays operated: it only drops out below 3.6 V","It drops out: 10 V is below its 15.2 V pull-in","It chatters between open and closed"],"answer":0,"explain":"Pulling the armature in across a wide gap takes 15.2 V. Once it is in, the gap is small and the pull (N·I)² / gap² is strong: it holds down to 3.6 V.","why":["","Pull-in is the voltage needed to close it from rest. A closed armature sits close to the core and needs far less current to stay.","Chattering would need the supply to cross both thresholds, and 10 V sits between them."]},{"question":"The relay adder is widened from 4 to 32 bits. How long after the operands change is the sum settled?","options":["1 relay step (8.2 ms)","32 relay steps, one per bit","68 relay steps"],"answer":0,"explain":"Only the operand relays move, all together. The carry is never a coil: it passes through contacts that are already closed.","why":["","A carry would ripple bit by bit if each bit had to operate a relay. Here it only passes through contacts.","That is the 32-bit <span data-ahead=\"ripple\">ripple-carry adder (carry passed from column to column)</span> built from NAND bricks, a relay per NAND: then the carry waits for a coil in every gate."]},{"question":"In the self-holding relay, how does reset clear the bit?","options":["It operates a relay whose break contact sits in the line that feeds k","It opens k's own make contact","It releases the set relay"],"answer":0,"explain":"k is fed through its own make contact from a holding line that runs through the reset relay's break contact. Reset opens that line, k drops out, and its make contact opens behind it.","why":["","k's make contact opens only after k has dropped out. Reset has to cut the current first, somewhere else in the path.","After the set pulse the set relay is already released. k is fed through the holding line, not through the set relay's contact."]}],
  "tubes": [{"question":"One tube plate must feed six grids. What does a tube machine do?","options":["Put a cathode follower in front of the fan-out","Nothing: a plate can drive any number of dividers","Wire the six grids straight to the plate"],"answer":0,"explain":"Each divider loads the plate toward the bias rail; past two the margins are thin and at four the chain fails. A cathode follower drives the wide net instead.","why":["","Each divider pulls the plate toward -150 V: one already holds a cut-off plate at 241 V, and at four the margins are gone.","A grid at plate level (81 V or more) conducts for ever: the next tubes would never turn off."]},{"question":"Why is NOR, not a series stack, the natural gate for triodes?","options":["In series the upper tube's cathode would float, which moves its grid levels; in parallel each input costs one section","NOR needs fewer resistors","Triodes in series conduct backwards"],"answer":0,"explain":"Parallel triodes all have their cathodes on ground, so every grid sees the same levels. A series stack lifts the upper cathode off ground.","why":["","Each input needs its own divider either way. The trouble with a series pair is the upper cathode, not the resistor count.","A triode never conducts backwards, in series or not: current still crosses each tube from plate to cathode."]},{"question":"About how many tube steps fit in one relay step?","options":["About 8300","About 40 000","About 10"],"answer":0,"explain":"8.2 ms against about 1.0 µs: a relay waits for iron to move, a tube for a resistor to charge the next grid.","why":["","That is how much slower a tube step is than a 25 ps NAND in <span data-ahead=\"cmos\">CMOS (the transistor logic of chapters 1 to 3)</span>.","A relay step is milliseconds and a tube step about a microsecond: nearly four orders of magnitude apart."]}],
  "cards": [{"question":"Which holes does the 029 punch for the letter T?","options":["0 and 3","11 and 3","12 and 3","0 and 2"],"answer":0,"explain":"The 0-zone letters start at 2: S is 0-2, so T is 0-3.","why":["","11-3 is L: zone 11 holds J to R.","12-3 is C: zone 12 holds A to I.","0-2 is S. The 0 zone starts at digit 2, so T is one further."]},{"question":"A dropped deck carries sequence numbers from 1 to 999. How many passes through the sorter put it back in order?","options":["3","1","10"],"answer":0,"explain":"One pass per digit of the key, rightmost first: units, tens, hundreds.","why":["","One pass sorts on one column only: cards with the same last digit stay mixed on the others.","Ten is the number of digit pockets, not of passes. The passes follow the number of digits in the key."]},{"question":"The reader holds next at 1 and needs 2 edges to feed each card. How many rising edges take a 10-card deck?","options":["28","10","30"],"answer":0,"explain":"A card is taken at an edge, then the reader needs 2 edges to bring the next: 10 + 9 × 2 = 28.","why":["","A card is taken only at an edge where one is ready. After each one the reader needs 2 more edges to feed the next.","No feed time follows the last card: after it the hopper is empty."]}],
  "mosfet": [{"question":"An NMOS (Vt = 0.45 V) has Vgs = 0.9 V and Vds = 1.2 V. Which region is it in?","options":["Linear","Saturation","Cut-off"],"answer":1,"explain":"Vgs − Vt = 0.45 V and Vds = 1.2 V is above it: the drain end of the channel has pinched off.","why":["Linear needs Vds below Vgs − Vt, here 0.45 V. A large Vgs does not make it linear; the overdrive against Vds does.","","Cut-off needs Vgs below Vt. At 0.9 V a channel exists at the source end."]},{"question":"An NMOS has Vgs = 0.95 V and Vds = 1.5 V (Vt = 0.45 V). Vgs rises to 1.45 V, Vds unchanged, and it stays in saturation. The drain current becomes about:","options":["Twice as large","Four times as large","The same: in saturation the current no longer depends on the voltages"],"answer":1,"explain":"Id = k·(Vgs − Vt)²/2: the overdrive doubles from 0.5 V to 1.0 V, so the current grows four times (the λ factor is unchanged, since Vds is).","why":["The current goes as the square of the overdrive Vgs − Vt, not as Vgs.","","Saturation makes the current (nearly) independent of Vds. The gate still sets it."]},{"question":"An output's load grows from 5 fF to 10 fF, and its transistor is made twice as wide. Its energy per 0 → 1 → 0 swing becomes:","options":["About twice as large","The same: the wider transistor makes up for it","Four times as large"],"answer":0,"explain":"Energy per swing is C·V²: it follows the load alone. The wider transistor doubles the current, so the delay, C·ΔV / I, stays the same.","why":["","Width buys current, which shortens the delay. The charge moved per swing, C·V, still doubles.","Energy goes as V², not as C²: doubling C doubles it."]}],
  "inverter": [{"question":"How many devices does a three-input <span data-ahead=\"nor\">NOR (a gate whose output is 1 only when every input is 0)</span> take in pseudo-NMOS, and in CMOS?","options":["3 NMOS and one always-on pull-up (a resistor here; in silicon a grounded-gate PMOS, so 4 transistors), against 6 transistors","3 NMOS and three pull-ups, against 6 transistors","3 NMOS and one pull-up, against 4 transistors"],"answer":0,"explain":"Pseudo-NMOS keeps the n parallel NMOS and replaces the whole PMOS network with one always-on pull-up: n + 1 devices against 2n.","why":["","One pull-up serves the whole gate: pseudo-NMOS replaces the PMOS network, one device per input, with a single always-on load.","A CMOS gate needs one PMOS per input as well as one NMOS per input: 2n = 6."]},{"question":"Where does a CMOS inverter spend its energy?","options":["Charging and discharging the capacitance it drives, at each transition","In a current from VDD to ground while y = 0","In the PMOS, for as long as y = 1"],"answer":0,"explain":"One network is always open, so with the input still no current flows. Each transition moves the charge of the load: that is the energy.","why":["","That is the pseudo-NMOS inverter. In CMOS the PMOS is off while y = 0, so there is no path from VDD.","With y held at 1 the PMOS conducts but the NMOS is off: once y has charged, no current flows."]},{"question":"A CMOS inverter's input is a slightly weak 1, a little below VDD. Its output is:","options":["A full 0: the NMOS connects y straight to GND","A slightly weak 0, passing the error on","Z: neither transistor is sure"],"answer":0,"explain":"The output comes from a rail, not from the input. A weak input still turns one network on and the other off, so the level is restored.","why":["","Passing the error on is what a restoring gate avoids: y is connected to GND, whatever the exact input voltage.","The NMOS is still on and the PMOS still off: one network conducts, so y is driven."]},{"question":"A 9-stage ring oscillator has a stage delay of 20 ps. What is its frequency?","options":["1 / (9 × 20 ps) = 5.6 GHz","1 / (2 × 9 × 20 ps) = 2.8 GHz","1 / (20 ps) = 50 GHz"],"answer":1,"explain":"A change goes round once to arrive inverted and a second time to restore: a period is 2N stage delays, 360 ps, so 2.78 GHz.","why":["One lap is half a period: the output has only made one edge.","","That is a single stage; the signal must pass all nine."]},{"question":"Why does a CMOS inverter chain restore a degraded logic level?","options":["Its gain exceeds 1 between V_IL and V_IH, and the curve is flat near the rails, so an off-level input leaves closer to a rail","Its output is a copy of the input delayed","Both transistors are always on"],"answer":0,"explain":"Outside the band the slope is below 1, so an input error shrinks stage by stage; inside it the gain is far above 1, so the output is pushed to a rail.","why":["","It is inverted, not copied, and a delay restores nothing.","Both conduct only inside the narrow band around V_M; elsewhere exactly one does."]}],
  "nand": [{"question":"A three-input CMOS NAND has six transistors. How are they arranged?","options":["Three PMOS in parallel, three NMOS in series","Three PMOS in series, three NMOS in parallel","Three PMOS in parallel, three NMOS in parallel"],"answer":0,"explain":"The output may fall to 0 only when every input is 1, so the pull-down needs all three NMOS in a chain, and any one input at 0 must pull up: PMOS in parallel.","why":["","That is the three-input NOR: its output is 1 only when every input is 0.","Then for mixed inputs both networks conduct at once: a short from VDD to GND, and y is neither 0 nor 1."]},{"question":"By logical effort, which gate is slowest to drive a given load at minimum input capacitance?","options":["NAND3, g = 5/3","NOR3, g = 7/3","NAND2, g = 4/3"],"answer":1,"explain":"A NOR stacks its weak PMOS: widening three in series costs 2n + 1 = 7 units of input capacitance against n + 2 = 5 for a NAND3.","why":["That is the NAND3: the stack is NMOS, the stronger device.","","The two-input NAND is the fastest of the three."]},{"question":"Why do chip designers prefer NAND to NOR?","options":["NAND puts the weaker PMOS in parallel, so at equal speed it is smaller","NAND needs fewer transistors","NOR is not functionally complete"],"answer":0,"explain":"Holes are two to three times slower than electrons. NOR stacks its PMOS in series, so they must be made wider to pull up as fast.","why":["","Both need four transistors.","NOR is complete too. The preference is about speed and area, not about what can be built."]},{"question":"On a CMOS NAND with a = 0 and b = 1, which transistors conduct?","options":["The PMOS whose gate is a, and the NMOS whose gate is b","Both PMOS","Both NMOS","None of them"],"answer":0,"explain":"A PMOS conducts on a 0 at its gate, an NMOS on a 1. The PMOS on a pulls y up to 1; the NMOS on b conducts, but the one on a is off, so there is no path to ground.","why":["","The PMOS on b has a 1 at its gate: it is off.","The NMOS on a has a 0 at its gate: it is off, so the series path is broken.","Then y would float. In CMOS one network always conducts."]}],
  "gates": [{"question":"Built from this chapter's boxes, how many NANDs does NOT(a OR b) take?","options":["4","2","3","1"],"answer":0,"explain":"4: an OR is two inverters and a NAND (3); inverting its output costs one more NAND used as NOT.","why":["","That is AND: one NAND, then one NAND as an inverter.","That is OR alone: its output still has to be inverted.","One NAND gives NOT(a AND b), not NOT(a OR b)."]},{"question":"A 2:1 multiplexer has its data input a tied to 0. As a function of s and b, what does it compute?","options":["s AND b","s OR b","s XOR b","NOT b"],"answer":0,"explain":"y = s ? b : 0. With s = 0 the output is 0; with s = 1 it is b. That is s·b.","why":["","With s = 0 the mux passes a, which is 0 whatever b is: OR would give b there.","With s = 1 the mux passes b unchanged; XOR would invert it.","A multiplexer only chooses between its inputs: nothing in it inverts the data."]},{"question":"In the four-NAND XOR, how many NAND delays lie on the slowest path from a to y?","options":["1","2","3","4"],"answer":2,"explain":"a → m = NAND(a, b) → a middle gate → the output NAND: three delays. The direct path a → middle gate → output is only two.","why":["One delay reaches only the first NANDs; y is at least one gate further.","That is the direct path a → middle gate → output. The path through the shared NAND m is one longer.","","XOR has four NANDs, but they are not in one chain: the two middle gates work side by side."]}],
  "binary": [{"question":"Write <code>0b0110_1101</code> in hexadecimal.","options":["<code>0x6D</code>","<code>0xD6</code>","<code>0x613</code>","<code>0x109</code>"],"answer":0,"explain":"0110 = 6 and 1101 = 13 = D, high group first: 0x6D (109 in decimal).","why":["","That reads the groups in the wrong order: the left four bits are the high digit.","Each hex digit covers four bits and runs 0–F: 1101 is the single digit D, not 13.","109 is the value in decimal, written with a hex prefix."]},{"question":"What is −5 in 8-bit two's complement?","options":["<code>0xFB</code>","<code>0xFA</code>","<code>0x85</code>","<code>0x05</code>"],"answer":0,"explain":"5 = 0000_0101. Invert: 1111_1010. Add 1: 1111_1011 = 0xFB. Check: 0xFB + 5 = 0x100, which wraps to 0.","why":["","That is the inverted bits without the +1 (one's complement): 0xFA + 5 = 0xFF, not 0.","That is sign and magnitude: the top bit set on top of 5. Two's complement does not keep the magnitude bits.","0x05 is +5: its top bit is 0."]},{"question":"An 8-bit adder adds <code>0xFF</code> and <code>0x02</code> and drops the carry out. What is the result?","options":["0x01: 1 read unsigned, and 1 read signed","0x01: 1 unsigned, but a signed overflow","0x101: 257 unsigned"],"answer":0,"explain":"Unsigned, 255 + 2 = 257 wraps to 1. Signed, the same bits are −1 + 2 = 1. One addition, two correct readings.","why":["","Signed, this is −1 + 2 = 1, well inside −128…127: no overflow. It is the unsigned sum that wrapped.","An 8-bit result has no ninth bit: the carry out leaves, and 255 + 2 wraps to 1."]}],
  "adders": [{"question":"A ripple-carry adder grows from 32 to 64 bits. What happens to its worst-case delay?","options":["It roughly doubles","It grows by a constant","It stays the same","It roughly quadruples"],"answer":0,"explain":"The carry crosses each full adder in turn, two NAND delays per bit: delay grows linearly with the width.","why":["","That is a tree, like the magnitude comparator, or the fast adders of chapter 16. Here each column waits for the carry from the one to its right.","The columns sit side by side, but they do not work in parallel: each needs its neighbour's carry first.","The carry crosses each full adder once: the delay grows with n, not n²."]},{"question":"In the adder/subtractor, why is <code>sub</code> wired to the carry-in as well as to the XORs?","options":["To add the 1 in a + ¬b + 1","To invert a","To signal an overflow"],"answer":0,"explain":"The XORs give ¬b, which is −b − 1 in two's complement. The carry-in adds the missing 1, for free.","why":["","Only b passes through XORs; a goes straight into the full adders.","Overflow has its own output, v. The carry-in completes the negation: ¬b alone is −b − 1."]},{"question":"Why is the 32-bit comparator 27 NAND delays deep while the subtractor's carry out (the inverted borrow) takes 70?","options":["It merges bit fields in a tree, so its depth grows with log n","It is built from faster gates","It computes no difference, so it has fewer gates","It compares only the top bits"],"answer":0,"explain":"Each combine cell decides a field from two halves: \"the higher one decides, unless equal\". log₂ 32 = 5 levels of cells replace a 32-stage chain.","why":["","Every gate on this site is a NAND with one delay; only the structure differs.","It costs about as many NANDs as the subtractor (some 450). What changes is the shape: a tree in place of a chain.","The top bits decide only when they differ; when they are equal, every lower field still counts."]}],
  "routing": [{"question":"A 16:1 multiplexer is built as a tree of 2:1 muxes. How many muxes, and how many levels?","options":["15 muxes, 4 levels","16 muxes, 4 levels","8 muxes, 4 levels","15 muxes, 15 levels"],"answer":0,"explain":"Each level halves the candidates: 8 + 4 + 2 + 1 = 15 muxes in log₂ 16 = 4 levels.","why":["","A tree of 2:1 muxes has one node fewer than it has leaves: 8 + 4 + 2 + 1 = 15.","Eight muxes are only the first level: their eight winners still need 4 + 2 + 1 more.","That is a chain. In a tree the muxes of one level work side by side, and each level halves the candidates."]},{"question":"An 8-input priority encoder sees first r = 0 (no request), then r = 0b0000_0001. Which output tells the two apart?","options":["v: 0, then 1","y: 0, then 1","None: every output is 0 both times"],"answer":0,"explain":"Request 0 has index 0, so y = 0 either way. The valid bit v says whether any request is raised.","why":["","Request 0 has index 0: y = 0 in both cases.","That is the plain encoder's problem. The priority encoder adds v for exactly this case."]},{"question":"A 3 → 8 decoder with enable has a = 5 and en = 0. Which outputs are 1?","options":["None","y5","All but y5","y0"],"answer":0,"explain":"en is an input of every output's AND gate. With en = 0 no output can rise, whatever the address.","why":["","en is the fourth input of every AND gate, y5's included: with en = 0 it stays 0.","A decoder is one-hot or all zeros; nothing in it inverts the outputs.","en does not change the address: it gates every output, so none rises."]}],
  "latches": [{"question":"A D latch has e = 1 while d goes 0 → 1 → 0. What does q do?","options":["It follows d: 0, 1, 0","It keeps its old value","It changes only at the next clock edge","It goes to 1 and stays there"],"answer":0,"explain":"With e = 1 the latch is transparent: q follows d after a few gate delays, for as long as e stays 1.","why":["","That is the closed latch, e = 0.","That is the flip-flop. A latch has no edge: it is transparent for as long as e = 1.","An SR latch set once would hold 1, but the D latch drives reset from ¬d, so d = 0 resets it again."]},{"question":"In the master–slave flip-flop, clk is low. Which latch is transparent?","options":["The master","The slave","Both","Neither"],"answer":0,"explain":"The master follows d while the clock is low (d flows into it while the slave holds q). At the rising edge it closes on d, and the slave opens to show it.","why":["","The slave is open while clk is high: it shows what the master caught at the rising edge.","Then d would race straight through to q. The opposite enables exist to prevent exactly that.","The two swap at the edge; apart from the inverter's one-delay lag, exactly one is open."]},{"question":"Why do designers keep an SR latch from seeing s_n and r_n released at the same instant?","options":["The pair balances at its metastable point: noise picks the winner, and how long that takes has no bound","It always resets the latch","It shorts the supply to ground","It leaves q = q̄ = 1 for good"],"answer":0,"explain":"Both NANDs see (1, 1) and start to switch together. In silicon the outputs hang near mid-rail until mismatch and noise, amplified by the loop, tip them: the chance of still being undecided after t falls as e^(−t/τ), small but never zero.","why":["","Neither input wins by design: mismatch and noise decide, and nothing bounds when.","Each NAND is a complete CMOS gate and never shorts the supply. Both outputs at 1 is a legal logic state, just not a useful one.","Both outputs are 1 only while both inputs are held low; on release the pair has to fall one way."]},{"question":"Between two flip-flops the slowest logic is 20 NAND delays; clk-to-q is 3 and setup 2. What is the shortest safe clock period?","options":["25 delays: clk-to-q + logic + setup","20 delays: the logic alone","23 delays: setup is met at the edge itself","22 delays: clk-to-q overlaps the logic"],"answer":0,"explain":"After the edge q needs 3 delays to change, the logic 20 more, and the next flip-flop wants d settled 2 delays before its edge: 25.","why":["","The logic only starts once q has changed (clk-to-q), and must finish before the capturing flip-flop's setup window.","d must be settled a setup time before the edge, not at it: the master needs that long to take it.","The logic's input is q: it cannot start before q has changed."]}],
  "registers": [{"question":"An 8-bit LFSR with maximal taps steps through how many states before it repeats?","options":["255","256","8","16"],"answer":0,"explain":"Every non-zero value once: 2⁸ − 1 = 255. All zeros is excluded because it never leaves.","why":["","The all-zero state feeds back a 0 (an XOR of zeros) and maps to itself, so the cycle visits every value but that one.","That is an 8-bit ring counter: one 1 circulating through 8 flip-flops.","That is an 8-bit Johnson counter: 2n states."]},{"question":"A JK flip-flop has j = 1 and k = 1. What happens at each rising edge?","options":["q toggles","q becomes 1","q becomes 0","Nothing defined: it is the forbidden input"],"answer":0,"explain":"It loads j·¬q + ¬k·q = ¬q: it flips on every edge, like a T flip-flop with t = 1.","why":["","That is j = 1, k = 0: set.","That is j = 0, k = 1: reset.","The SR latch's forbidden input is exactly what JK gives a meaning: j·¬q + ¬k·q = ¬q."]},{"question":"The 101 detector's y = x·s1 is a Mealy output. What does that ask of the logic that reads y?","options":["To sample y at a clock edge: y follows x, glitches included","Nothing: y changes only at clock edges","To wait a cycle: y comes one cycle late","To give y its own flip-flop, without which it is undefined"],"answer":0,"explain":"A Mealy output reads the inputs directly, so it moves whenever x moves. Read at the clock edge, it is correct a cycle earlier than a Moore output.","why":["","That is a Moore output, a function of the state alone.","That is the Moore version: it recognises the pattern one edge after the Mealy y.","y is plain logic on x and s1, defined at every instant. The Moore version adds a state (S3), not an output flip-flop."]}],
  "memory": [{"question":"A RAM grows from 16 to 32 words of 8 bits. What happens to its read path?","options":["Each bit's mux tree gains one level: 5 instead of 4","The number of levels doubles","Nothing: the read path depends on the width","It now waits for the clock"],"answer":0,"explain":"The tree has log₂(words) levels: one more address bit, one more level of 2:1 muxes. The width sets how many trees run side by side.","why":["","Levels grow with the address bits, log₂ of the words: doubling the words adds one level.","The width sets how many mux trees run side by side; the number of words sets how deep each one is.","Reading stays asynchronous at any size; only writes wait for the edge."]},{"question":"A 4-word FIFO has 3-bit pointers. The write pointer is 0b110 and the read pointer 0b010. Is it empty, full or neither?","options":["Full","Empty","Neither: two words are held"],"answer":0,"explain":"The low two bits name the same slot (2); the extra bit differs, so the writer is a whole lap ahead: four words held.","why":["","Empty needs all three bits equal. The extra bit differs: the writer is a lap ahead.","Both pointers name slot 2, and 6 − 2 = 4 words: the whole capacity."]},{"question":"When is a PLA cheaper than a ROM for the same function?","options":["When the outputs need few product terms, each with few inputs","Always: it is a ROM with fewer gates","When the contents must change after manufacture","When every input pattern gives a different output"],"answer":0,"explain":"A ROM decodes every input pattern. A PLA pays per product term, so it wins when the minimized function has few, small terms (the 7-segment font: 28 terms of 2 or 3 inputs).","why":["","Not always: the PLA pays per product term, and a function needing many wide terms can cost more than the full decoder a ROM shares among all its outputs.","Both are wired when built here. Rewritable contents need cells that store each connection as charge, as flash does.","Then every input pattern needs its own term: the PLA rebuilds a full decoder and saves nothing."]}],
  "alu": [{"question":"8-bit a = 0x7F (127), b = 0x80 (−128). The ALU computes a − b = 0xFF. Is a &lt; b, signed?","options":["No: N ⊕ V = 0, because the subtraction overflowed","Yes: N = 1","Yes: there is no carry out","The flags cannot tell; a comparator is needed"],"answer":0,"explain":"127 − (−128) = 255 does not fit in 8 signed bits. The result 0xFF reads as −1 (N = 1), but V = 1, so N ⊕ V = 0: a ≥ b, which is right.","why":["","N alone is the sign of a wrapped result. Here the subtraction overflowed, so the sign bit lies.","No carry out answers the unsigned question: 0x7F &lt; 0x80 unsigned is true, but the signed answer is the opposite.","The adder's flags hold both answers. That is why the ALU contains no comparator."]},{"question":"How many mux stages does the shift itself need in a 64-bit barrel shifter?","options":["6","64","32","5"],"answer":0,"explain":"The shift amount has log₂ 64 = 6 bits; stage j shifts by 2<sup>j</sup> or passes through. 6 rows of 64 MUX2, plus the reversal rows for left shifts.","why":["","That is one stage per possible shift amount. Decomposing the amount in binary needs one stage per bit of it.","Stage count follows the bits of the shift amount, not half the width.","Five stages reach shifts up to 31: enough for RV32, not for 64-bit words."]},{"question":"<code>srl</code> and <code>sra</code> share funct3 = 101. What tells the ALU which one to do?","options":["funct7[5] (instruction bit 30), passed on as ctl[3]","The opcode","A decoder reading all seven funct7 bits","The sign of rs2"],"answer":0,"explain":"For an R-type ctl = {funct7[5], funct3}: 0101 is SRL, 1101 SRA, and the same bit picks SUB (1000) over ADD (0000). For OP-IMM a few gates pass bit 30 only when funct3 = 101 (srli / srai): in addi or andi that bit is imm[10], and <code>addi a0, a0, -1</code> would otherwise subtract.","why":["","Both are R-type (or both OP-IMM, the forms that carry a constant): the opcode says where the operand comes from, not which shift.","Only bit 5 of funct7 differs between them: one gate passes it on, no wider decoder.","rs2 gives the shift amount. The fill bit comes from a, and only when ctl says arithmetic."]}],
  "regfile": [{"question":"Why does the register file have two read ports?","options":["An R-type instruction reads rs1 and rs2 in the same cycle","One port reads while the other writes","One of them serves x0","To read 64-bit values"],"answer":0,"explain":"<code>add rd, rs1, rs2</code> needs both operands at once in a machine that finishes one instruction per cycle. One port would take two cycles; one result per instruction needs only one write port.","why":["","Writes have their own synchronous port; both read ports only read.","x0 needs no port: it is a constant on the bundled bus, selected like any other word.","RISC-V registers are 32 bits, and each port returns one register."]},{"question":"<code>addi x0, x5, 1</code> executes. What happens?","options":["Nothing visible: the write to x0 goes nowhere","x0 holds x5 + 1 until the next write","The processor stops with an error","x5 is incremented"],"answer":0,"explain":"x0 has no storage, so the result is lost and x0 still reads 0. <code>addi x0, x0, 0</code> is the canonical <code>nop</code>.","why":["","There is nothing to hold the value: x0's slot on the read bus is wired to 0.","Writing x0 is legal; RISC-V relies on it for nop and for discarding results (j is jal x0).","rd is x0; rs1 = x5 is only read."]},{"question":"A third read port on this 32 × 32 register file adds about…","options":["4000 NANDs: one more 32:1 tree of 32-bit words","two transistors per bit","nothing: the bundled bus already reaches every register","a second set of 31 registers"],"answer":0,"explain":"31 MUX2 per bit × 32 bits × 4 NANDs = 3968 NANDs. Port count is a first-order cost, which is why wide superscalar cores fight over register-file ports.","why":["","That is the price with custom multi-ported memory cells, not with a mux tree built from NANDs.","The bus brings every word to the port, but each port still needs its own selector to pick one.","Ports share the storage; only the selection logic is duplicated."]}],
  "isa": [{"question":"In <code>sw a1, 8(a0)</code>, what occupies bits 11:7, where an R-type keeps rd?","options":["imm[4:0]","rs2","rd","funct3"],"answer":0,"explain":"S format: imm[11:5] in bits 31:25, imm[4:0] in 11:7. Splitting the immediate keeps rs1 and rs2 where every other format has them.","why":["","rs2 stays at 24:20 in every format that has one: that is the point of the layout.","A store writes no register, so S has no rd; its slot carries the low immediate bits.","funct3 stays at 14:12 in every format that has one."]},{"question":"How does <code>jal ra, 2048</code> store its offset?","options":["As imm[20:1], scrambled: bit 11 of the offset lands in instruction bit 20","As 2048 in bits 31:20, like an I-type immediate","As 512 words","It cannot: jal reaches only ±2 KiB"],"answer":0,"explain":"J stores imm[20|10:1|11|19:12] in bits 31:12; bit 0 is always 0 and not stored. 2048 sets only imm[11], which sits in instruction bit 20. Range: ±1 MiB.","why":["","An I-type immediate is 12 bits signed (−2048 … 2047): 2048 would not even fit, and J has 20 bits to spend.","Offsets count halfwords, not words, so that 2-byte compressed instructions can be targets.","That is the range of a 12-bit immediate. J's 20 bits of halfwords reach ±1 MiB."]},{"question":"<code>li a0, 0x12345</code> assembles to how many words?","options":["Two: lui, then addi","One: li is an instruction","One addi, since the value is positive","Three"],"answer":0,"explain":"<code>lui a0, 0x12</code> sets the upper 20 bits, <code>addi a0, a0, 0x345</code> adds the low 12. addi sign-extends, so when bit 11 of the constant is set lui takes one more: <code>li a0, 0x12845</code> is <code>lui a0, 0x13</code>; <code>addi a0, a0, -1979</code> (0x13000 − 0x7BB). Pass 1 must know the size to place every label after it.","why":["","li is a pseudo-instruction: RV32I has no li opcode.","addi's immediate is 12 bits signed (−2048 … 2047); 0x12345 = 74 565 does not fit.","lui supplies 20 bits and addi 12: two instructions cover any 32-bit constant."]}],
  "cpu": [{"question":"For <code>sw t0, 8(a0)</code>, which control settings are right?","options":["MemWrite = 1, ALUSrcB = immediate, RegWrite = 0","MemWrite = 1, RegWrite = 1, ResultSrc = memory","RegWrite = 1, ALUSrcB = rs2","MemWrite = 0, ResultSrc = ALU"],"answer":0,"explain":"The ALU adds rs1 and imm<sub>S</sub> for the address, rs2 is the data, and nothing is written back.","why":["","A store writes no register: RegWrite = 1 would overwrite whichever register the immediate bits in 11:7 happen to name.","That is add: an R-type whose result is written back.","MemWrite = 0 makes it no store at all."]},{"question":"<code>jal ra, f</code>: which value does the result mux send to the register file?","options":["PC + 4","PC + imm<sub>J</sub>","The ALU result","The immediate"],"answer":0,"explain":"ra gets the return address from the +4 adder; the target PC + imm<sub>J</sub> goes to the PC.","why":["","That is the jump target: it goes to the PC, not to ra.","The return address comes from the +4 adder; nothing the ALU computes is written back.","The result mux passes the immediate for lui, not for jal."]},{"question":"Which block of the control unit has real logic beyond decoding the opcode?","options":["ALUControl, which passes funct7[5] and funct3 for an R-type, only funct3 for OP-IMM, and forces ADD for address arithmetic and SUB for branches","RegWrite, which needs all of funct7","MemWrite, which depends on funct3"],"answer":0,"explain":"Every other output is an OR of opcode classes. ALUControl also reads funct3 and funct7, with the exceptions that make one adder serve addresses, compares and arithmetic.","why":["","RegWrite is the OR of the classes that write a register: opcode alone.","MemWrite is the store class and nothing else."]},{"question":"Replacing the ripple adder by a <span data-ahead=\"prefix\">Kogge–Stone adder (a parallel-prefix adder: its carry takes about log₂ n levels)</span> cuts the ALU from 93 to 41 delays. By how much does the clock period fall?","options":["From 155 to 103: the same 52 delays, since the path crosses the ALU once","To a third, since the ALU is 93 of 155","Not at all: the load path is the longest"],"answer":0,"explain":"The longest path crosses the ALU once, so its length falls by exactly what the ALU saves. What remains (fetch, decode, next-PC select: 62 delays) is now 60% of the period.","why":["","Only the ALU part of the path shrinks; the 62 delays around it stay.","No load is the longest: its word reaches the result mux long before the ALU result does. The path that sets the period is the branch compare through the next-PC select, and it shrinks with the ALU."]},{"question":"A program of mostly <code>addi</code> runs on the single-cycle CPU. Why is each instruction no faster than a load?","options":["The clock period is fixed by the longest path any instruction can take","addi uses the data memory too","The register-file write takes the whole cycle","It is faster: each instruction takes its own time"],"answer":0,"explain":"One instruction per cycle at one period: the cycle must fit the slowest instruction, and addi wastes the slack. Designs that split an instruction over several cycles, or overlap instructions, exist to recover it.","why":["","addi never touches the data memory; its path ends at the result mux.","The write happens at the clock edge; it is not what makes the cycle long.","A synchronous design has one clock period for every instruction."]}],
  "python": [{"question":"<code>n // 2</code> compiles to one <code>srai</code>. Why is that exactly the floor of n / 2 (what Python's <code>//</code> gives) for negative n too?","options":["An arithmetic shift right rounds toward minus infinity, as // does","Python rounds toward zero, and so does srai","It is not exact: the compiler accepts an error for negative n","srai calls the divide routine for negative n"],"answer":0,"explain":"Shifting a two's-complement number right by one, copying the sign bit in, is ⌊n / 2⌋: −7 becomes −4. Python's // is also the floor. Dividing by a power of two without flooring (C's, toward zero) needs a correction; Python's needs none.","why":["","Python's // is the floor: −7 // 2 is −4, not −3.","Both are the floor: the test suite checks every edge case against the interpreter.","srai is one instruction; there is no call."]},{"question":"Why does a top-level variable that a function reads live in data memory, and not in a register?","options":["The function uses the registers for its own variables and saves them on entry; only memory is shared by every function","Registers are slower than memory","RV32I cannot read a register in a function","Python requires globals to be in memory"],"answer":0,"explain":"Each function saves the s registers it uses and gives them back on return. A global in s3 would be invisible inside a function that keeps its own variable there; a word of data memory has one address for everyone.","why":["","A register is read in the same cycle; a load also takes one cycle on this CPU, but needs an instruction more.","Any instruction can read any register.","Python says nothing about registers; this is the compiler's choice."]},{"question":"fib(n − 1) + fib(n − 2): where is fib(n − 1)'s result while fib(n − 2) runs?","options":["On the stack: t0 is pushed around the second call, because the callee uses t0 too","In t0, which the callee never touches","In a0, the return register","In data memory at a fixed address"],"answer":0,"explain":"Temporaries are the caller's to save: the compiler stores the live ones (here t0) below sp before the call and loads them after. The stack panel shows the word labelled \"t0: waiting across a call\".","why":["","The callee evaluates its own expressions in t0–t6.","a0 carries fib(n − 2)'s result back, overwriting it.","A fixed address would be overwritten by the recursion's deeper calls."]}],
  "fastadd": [{"question":"Built from 2-input NANDs only, why is the 4-bit carry-lookahead adder deeper than the 4-bit ripple adder?","options":["Its wide ANDs and ORs become trees of 2-input gates","It computes the carries one after another","It chains four full adders and adds lookahead on top","g + p·c cannot be built from NANDs directly"],"answer":0,"explain":"c₄ needs a 5-input OR of up-to-5-input ANDs. From 2-input NANDs each becomes a tree: 15 delays against ripple's 12. Lookahead pays with wide gates, or hierarchically at larger widths.","why":["","Every carry is computed independently, in parallel: that is the point of lookahead.","It has no full adders: sums come from p ⊕ c, carries from the g / p expressions.","NAND is complete, and g + p·c is two NAND levels. The cost is the width of the terms."]},{"question":"Static timing says 155, yet at period 140 the sum program still ends with the right result. Why?","options":["The paths exercised in those cycles were shorter than the worst case","Static timing is wrong about this CPU","The simulator waits for the logic to settle","Early edges are ignored"],"answer":0,"explain":"The worst path needs a particular pattern of carries and opcodes. When no cycle exercises it, an early edge still captures settled values. That gap is the overclocker's headroom and the reason for a guard band.","why":["","Static timing is right about the worst path; that path simply did not carry the last change in those cycles.","With a period set, edges come on schedule, finished or not: that is how 130 breaks the program.","An early edge captures whatever is on the wires: at 130 that is a half-rippled result."]},{"question":"With Kogge–Stone adders the period drops from 155 to 103 NAND delays. What would shorten it next?","options":["Faster decode, immediate mux, ALU result mux and zero detector","An even faster adder","A faster register-file write","Nothing: 103 is the limit for this instruction set"],"answer":0,"explain":"Fix the worst path and the next one appears: the new critical path runs through decode, the immediate mux, the ALU's result mux and its zero detector.","why":["","The 32-bit Kogge–Stone is now under 20 NAND delays, a minority of the path: shaving it further moves little.","The critical path is a branch: it ends at the PC and never writes the register file.","Cutting the path into pieces is the next chapter's method: that CPU runs at 93 with these adders."]}],
  "pipeline": [{"question":"<code>add a0, a1, a2</code> then <code>sub t0, a0, a1</code>. Where does sub get a0?","options":["From the register file","Forwarded from EX/MEM","Forwarded from MEM/WB","It stalls one cycle"],"answer":1,"explain":"When sub is in E, add is one stage ahead with its result in EX/MEM. M is the most recent writer, so it wins.","why":["add writes a0 in W, two cycles after sub reads its registers in D: the register file still holds the old value.","","That is distance 2, with one instruction between them.","An ALU result is ready at the end of E, in time to forward. Only a load at distance 1 stalls."]},{"question":"<code>lw t0, 0(a0)</code> then <code>add t1, t0, t0</code>. How many bubbles?","options":["None: forwarding covers it","One","Two"],"answer":1,"explain":"The word arrives at the end of M, when add should already be in E: one stall, then forwarding from W.","why":["Forwarding moves a value that exists. The loaded word exists only at the end of M, one cycle too late for E.","","After one stall the load is in W and add in E: W forwards it. A second bubble would be wasted."]},{"question":"While an instruction is in M, where are its control bits (register write, memory write…)?","options":["In EX/MEM, travelling with it","In the control unit, which decodes it again each stage","In IF/ID"],"answer":0,"explain":"Control is decoded once in D and carried along in the pipeline registers, so each stage acts on its own instruction.","why":["","The control unit only sees the instruction in D. By the time this one reaches M, it is decoding the instruction two behind it.","IF/ID holds the instruction now in D, two behind this one."]}],
  "pipepay": [{"question":"Look-ahead forwarding compares the sources of the instruction in D with rdE and rdM. Why those two?","options":["Next cycle, when it reaches E, those instructions will be in M and W","They are the registers it will write","They are the only ones the register file cannot read","Comparing in D needs fewer bits"],"answer":0,"explain":"Forwarding in E takes values from M and W. One cycle earlier, those instructions are in E and M, so their destinations are already known.","why":["","rdE and rdM belong to the instructions ahead of it; its own destination is rdD.","The register file can read any register; the problem is that those two have not written theirs yet.","Register numbers are 5 bits in every stage. The gain is time: the comparison leaves E's critical path."]},{"question":"A loop branch is taken 9 times, then falls through, and the loop runs again. With a <em>1-bit</em> predictor, how many mispredictions per pass, after the first pass?","options":["2","1","0","10"],"answer":0,"explain":"The exit mispredicts (predicted taken) and flips the bit to not-taken, so the first branch of the next pass mispredicts too.","why":["","That is the 2-bit counter: one not-taken exit does not change its prediction.","The exit is always mispredicted: the predictor has just seen nine takens.","A 1-bit predictor is right whenever the outcome repeats, which is 8 times out of 10."]},{"question":"The predictor lengthens the balanced pipeline's period from 59 to 70 NAND delays. When does it still pay?","options":["When the CPI saved on flushes outweighs a period 19% longer","Never: a longer period is always slower","Always: the period does not matter","Only on programs without loops"],"answer":0,"explain":"Time per instruction = CPI × period. In a loop the flushes saved can outweigh the longer period; straight-line code pays it for nothing. Here it is about a draw: CPI 1.51 → 1.30 (−14 %) against the period's +19 %; fib and gcd gain, mul (a six-pass loop whose inner branch follows the multiplier's bits) loses.","why":["","A lower CPI can more than make up for a longer period: the product is what counts.","Every cycle pays the longer period, flush or not. On code with few taken branches the predictor saves little.","Loops are where prediction helps most: their branch is taken almost every iteration."]}],
  "io": [{"question":"<code>sh</code> writes to address 6. Which byte enables are raised (be<sub>3</sub>…be<sub>0</sub>)?","options":["1100","0011","0110","None: the address is misaligned"],"answer":0,"explain":"Address 6 is word 1, byte offset 2: the half goes to lanes 2 and 3. The low two address bits pick the lanes, the rest pick the word.","why":["","That would be address 4: bytes 0–1 of the word.","Bytes 1–2 would need an odd address, which is misaligned for a halfword.","A halfword is aligned at any even address, and 6 is even."]},{"question":"Which of these accesses is misaligned?","options":["<code>lw</code> from address 6","<code>lh</code> from address 6","<code>lb</code> from address 7","<code>sw</code> to address 8"],"answer":0,"explain":"An aligned word sits on a 4-byte boundary; address 6 spans two words. RISC-V lets a core either split such an access in hardware or <span data-ahead=\"traps\">trap (jump to a software handler)</span>; the complete CPU raises a misaligned-load exception (chapter 20).","why":["","A halfword needs only an even address.","A byte can sit at any address.","8 is a multiple of 4."]},{"question":"How does the CPU print to the console without a print instruction?","options":["A store to an address with bit 31 set goes to the I/O unit, which sends the byte to the console","funct3 of <code>sb</code> selects a console mode","The console reads the data memory every cycle","Only an <code>ecall</code> can print"],"answer":0,"explain":"Memory-mapped I/O: the address decides where a store goes. Devices get addresses, and ordinary loads and stores talk to them.","why":["","funct3 only gives the access size and sign; the address decides where the store goes.","Nothing watches the data memory: the store never reaches it, the I/O unit takes it instead.","An ecall hands control to a software handler (chapter 20), and that handler still prints with a store to the console address."]}],
  "traps": [{"question":"An <code>ecall</code> traps to a handler. What must the handler do before <code>mret</code> so that the program continues after the ecall?","options":["Add 4 to mepc","Nothing: mepc already points past the ecall","Set MIE","Clear mcause"],"answer":0,"explain":"mepc holds the address of the trapping instruction itself, so a fault can be fixed and retried. For an ecall that would call the OS again forever.","why":["","mepc points at the ecall itself; returning there would trap again.","mret restores MIE from MPIE by itself.","mcause is only read by the handler; mret does not look at it."]},{"question":"In the same cycle a timer interrupt is pending and enabled, and the instruction at the PC is illegal. What does mcause hold in the handler?","options":["0x80000007: interrupts come first","2: the illegal instruction","Both causes, ORed","11"],"answer":0,"explain":"The trap unit's chain puts interrupts ahead of every exception. mepc points at the illegal instruction, which has not run: after mret it executes and traps with cause 2.","why":["","The illegal instruction has not executed yet. The chain of muxes picks the interrupt, and the illegal instruction traps later, when it runs.","mcause holds one cause: the chain picks the highest-priority source.","11 is ecall."]},{"question":"Which registers does the hardware write on a trap, all in the same cycle?","options":["PC, mepc, mcause, mtval and mstatus (MIE, MPIE)","Only the PC","PC and ra, like jal","All 32 registers, saved to memory"],"answer":0,"explain":"Everything the handler needs to know where and why, and nothing the interrupted program owns.","why":["","Without mepc and mcause the handler could neither return nor know why it was called.","A trap must not touch any general register: the interrupted program may be using ra.","Saving registers is the handler's job, in software; the hardware saves only the PC and the cause."]},{"question":"The timer and the external interrupt are both pending and both enabled, with MIE = 1. What does mcause hold in the handler?","options":["0x8000000B: external interrupts outrank the timer","0x80000007: the timer, its cause number is lower","Whichever became pending first","Both bits, ORed into one cause"],"answer":0,"explain":"The privileged spec fixes the order among machine interrupts: external (11), then software (3), then timer (7). The CSR unit here picks external over timer; the timer stays pending in mip and is taken right after the handler's mret, unless the handler moved mtimecmp.","why":["","Priority is not the cause number: the spec puts external interrupts first, since a device cannot wait as long as a tick can.","The hardware keeps no arrival order: it looks at what is pending at the instruction boundary and picks by fixed priority.","mcause holds one cause; the other interrupt stays pending in mip."]}],
  "muldiv": [{"question":"A Wallace tree reduces 8 partial-product words to 2 with 3:2 rows. How many full-adder levels does that take?","options":["4","3","7"],"answer":0,"explain":"Each level turns every three words into two: 8 → 6 → 4 → 3 → 2. Then one fast adder adds the last two words.","why":["","Three levels would halve the rows each time (8 → 4 → 2 → 1), as a tree of two-input adders does. A 3:2 row keeps two words for every three.","Seven is the array: one adder per row after the first, each waiting for the one before."]},{"question":"In non-restoring division a step leaves a negative remainder. What does the next step do?","options":["Adds the divisor to twice the remainder","Puts the old remainder back, then subtracts the divisor from twice it","Subtracts the divisor from twice the remainder","Nothing: the division ends with quotient bit 0"],"answer":0,"explain":"2(r − d) + d = 2r − d: the same subtraction the restoring divider would have made after restoring. The quotient bit is still \"is the new remainder ≥ 0\".","why":["","That is restoring division. Non-restoring drops the restore multiplexer by never putting the old remainder back.","Subtracting from a negative remainder moves it further from the range; the sign says which way to correct.","Every step runs. A negative remainder only changes the next operation and, after the last step, triggers one correction."]},{"question":"Why can an SRT divider choose each quotient digit from only the top four bits of its remainder?","options":["With digits −1, 0 and +1 the regions overlap: near zero either neighbouring digit keeps the remainder in range, and a later digit corrects the error","The low bits of the remainder are always zero","Because the divisor is normalized, the low bits of the remainder cannot change the digit","It cannot: each step adds the full-width remainder first"],"answer":0,"explain":"+1 is correct anywhere in [0, 2d) and −1 anywhere in [−2d, 0). An estimate that is low by just under 1 still lands in a region whose digit is allowed, so no full-width carry is needed.","why":["","The low bits carry real information. They stop mattering for the choice only because a slightly wrong digit is repaired by later ones.","Normalization fixes the thresholds, but with only the digits 0 and 1 the choice would still need the exact sign of the full remainder.","That full-width carry chain is what SRT removes: the remainder stays as a sum word and a carry word."]},{"question":"<code>div</code> and <code>rem</code> with rs1 = −2³¹ (0x80000000) and rs2 = −1. What does RISC-V specify?","options":["Quotient 0x80000000 (−2³¹ again), remainder 0, and no trap","An overflow exception","Quotient 0x7FFFFFFF, saturated","Nothing: the result is implementation-defined"],"answer":0,"explain":"The true quotient +2³¹ does not fit in 32 bits, so it wraps to 0x80000000; the remainder is 0. RISC-V specifies it, as it specifies division by zero, so that division never traps (x86's idiv raises a divide error here). This M unit gets it for free: it divides 2³¹ by 1 unsigned, the signs agree so nothing is negated, and 2³¹ read as signed is −2³¹.","why":["","RISC-V has no integer arithmetic exceptions at all: overflow, like division by zero, gives a specified result.","Saturation would need a comparator and a constant the spec never asks for; the quotient simply wraps.","The spec fixes the result exactly, so every core and the golden model agree."]}],
  "cache": [{"question":"The gate-level direct-mapped cache has 4 lines of 4 words. Which address bits pick the line?","options":["Bits 5:4","Bits 3:2","Bits 1:0","Bits 7:6"],"answer":0,"explain":"Byte offset 1:0, word offset 3:2, index 5:4, tag above. 0x24 and 0x2C differ only in bits 3:2, so they share a line.","why":["","Bits 3:2 pick the word inside the line: the word offset.","Bits 1:0 are the byte offset within a word.","Those are the tag, compared with the stored tag once the index has picked the line."]},{"question":"A loop sweeps a 512-byte array again and again through a 256-byte fully associative cache with LRU replacement. After the first pass, what kind are its misses?","options":["Capacity","Conflict","Compulsory"],"answer":0,"explain":"The working set is twice the cache. Under LRU a sequential sweep evicts every line before it comes round again, so every new line misses on every pass.","why":["","A conflict miss needs one set to overflow while others have room. A fully associative cache is a single set.","Compulsory misses are the first touch of each line, and those all happen in the first pass."]},{"question":"In the write-back cache a load misses and its victim line is dirty. How long does the CPU stall?","options":["12 cycles: 4 to write the victim back, 4 of latency, 4 to fill","8 cycles, as for any miss","4 cycles: the write-back only","16 cycles: the write-back waits out the latency too"],"answer":0,"explain":"The miss controller counts 0–3 to write the victim back, 4–7 to wait, 8–11 to fill. A clean victim jumps from 0 to 5: 8 cycles.","why":["","Eight is a clean victim: the controller skips the write-back states.","The missing line still has to be fetched after the victim is written.","The victim's four words go out in states 0–3 with no wait of their own; only the fill waits for the memory."]}],
  "multicycle": [{"question":"How many cycles does <code>jalr</code> take on the multicycle CPU?","options":["5: Fetch, Decode, JALR, JAL, ALUWB","3, like a branch","4, like jal","1"],"answer":0,"explain":"JALR puts rs1 + imm in ALUOut; then it reuses the JAL state (PC ← target, ALUOut ← OldPC + 4) and ALUWB writes the return address.","why":["","A branch writes no register. jalr must compute its target from rs1 and also save the return address.","jal's target is ready after decode (OldPC + imm); jalr needs one more step for rs1 + imm before reusing JAL.","Only the single-cycle CPU finishes an instruction in one clock."]},{"question":"Why does the multicycle datapath need registers such as A, B and ALUOut that the single-cycle one does without?","options":["A value computed in one step must survive the clock edge into the next","They hold the microcode","They forward results between instructions","They replace the register file"],"answer":0,"explain":"Each step ends at a clock edge. Whatever the next step needs (the operands, the ALU result, the loaded word) must be captured in a register at that edge.","why":["","The microcode lives in the controller's ROM; these are datapath registers.","Only one instruction is in flight at a time: there is nothing to forward between.","The register file is still there; A and B hold the two values read from it for the next step."]},{"question":"Here microcode costs 6124 NANDs against 412 for the hardwired FSM. When is microcode worth it?","options":["When the control table is large and irregular, or must be changeable after manufacture","When the clock must be faster","Never: it only adds gates","When the instruction set is small and regular"],"answer":0,"explain":"A dense ROM stores a big table more cheaply than random logic, and can be rewritten. That is how System/360 spanned a family of machines and how x86 cores still patch bugs.","why":["","Both controllers give the same period here: microcode buys flexibility, not speed.","Our ROMs are mux trees; a real ROM is a dense transistor array. And System/360 and x86 used it for good reasons.","A small, regular table is where hardwired logic is cheapest, as RV32I shows here."]}],
  "float": [{"question":"In the chapter's 8-bit format (4 exponent bits, bias 7, 3 fraction bits), what is 0x4C = 0 1001 100?","options":["6","2","768"],"answer":0,"explain":"Exponent 1001 = 9, so 2<sup>9 − 7</sup> = 4; the significand is 1.100₂ = 1.5 with the hidden bit. 1.5 × 4 = 6.","why":["","That drops the hidden bit: a normal number's significand is 1.f, so 100 means 1.5, not 0.5.","That forgets the bias: the stored exponent 9 stands for 9 − 7 = 2."]},{"question":"A positive result is inexact with last kept bit 0, G = 1 and S = 1. Which modes round its magnitude up?","options":["RNE, RMM and RUP","Only RUP","RNE and RMM only","All five"],"answer":0,"explain":"G = 1 with S = 1 is more than half an ulp, so both nearest modes round up; RUP rounds any inexact positive result up. RTZ truncates, and towards −∞ a positive number truncates too.","why":["","Above the halfway point the two nearest modes round up as well: G = 1 with S = 1 is more than half an ulp.","RUP rounds a positive inexact result up whatever G and S are.","RTZ always truncates, and RDN (towards −∞) truncates a positive number."]},{"question":"The single-cycle RV32IF runs at 313 NAND delays with CPI 1, the pipelined one at 121. Above roughly what CPI does the pipeline lose?","options":["About 2.6","About 1.0","About 6, the number of stages"],"answer":0,"explain":"Time per instruction is CPI × period: 313 / 121 ≈ 2.6. \"Exception flags\" ran at about 2.7 (76 cycles for 28 instructions) and was the one program that lost.","why":["","At CPI 1 the pipeline is 2.6 times faster: it loses only when stalls eat that whole factor.","Overlap is the point of a pipeline: an instruction does not hold all six stages. Break-even is where CPI × 121 reaches 313."]}],
  "widths": [{"question":"A program's instructions are 60 % compressible. How large is it with C?","options":["70 % of its size","40 % of its size","60 % of its size"],"answer":0,"explain":"60 % of the instructions shrink from 4 bytes to 2, so they save half their space: 1 − 0.6 × 0.5 = 0.7.","why":["","That removes the compressible instructions entirely; they still take 2 bytes each.","That takes the share of 16-bit instructions as the size; each of them still takes half of what it did."]},{"question":"On RV64, a0 = 0x7FFF_FFFF. What does addiw a0, a0, 1 leave in a0?","options":["0xFFFF_FFFF_8000_0000","0x0000_0000_8000_0000","0x0000_0000_0000_0000"],"answer":0,"explain":"addiw adds on 32 bits: 0x7FFF_FFFF + 1 = 0x8000_0000, whose bit 31 is 1, so the sign extension fills the upper half with ones: −2³¹, as on RV32. addi would give 0x0000_0000_8000_0000.","why":["","That is addi's answer: the 64-bit sum, not sign-extended from bit 31.","Only the carry out of bit 31 would be lost, not the whole sum."]},{"question":"The C core runs at 196 NAND delays, the plain one at 155, both one instruction a cycle. Which is faster on the same program?","options":["The plain core, by about a quarter","The C core: the program is smaller","Neither: the work is the same"],"answer":0,"explain":"Time is instructions × period. The instruction count is the same (each 16-bit instruction is one 32-bit one), so the C core is 196 / 155 ≈ 1.26 times slower. Its gain is in bytes, which matter when fetch is the limit.","why":["","A smaller program fetches fewer bytes, but this core reads a whole window from its ROM every cycle anyway: the bytes are not the bottleneck here.","The work is the same; the clock is not. The expander lengthens the path every instruction takes."]}],
  "ooo": [{"question":"A program's dataflow limit is IPC 3.8. What does that bound?","options":["Every machine running it, whatever its width, window or predictor","Only an out-of-order machine with a 16-entry window","Only machines without branch prediction","The number of instructions fetched per cycle"],"answer":0,"explain":"The dataflow schedule keeps only the dependences and the latencies. Any real machine adds limits on top, so none can beat it.","why":["","The limit assumes an unlimited window; a 16-entry one can only do worse.","It assumes perfect prediction: branches cost nothing in it.","Fetch width is one of the limits it leaves out."]},{"question":"Which hazards does register renaming remove?","options":["WAR and WAW","RAW only","RAW, WAR and WAW","Structural hazards"],"answer":0,"explain":"WAR and WAW arise because two values share a register name. Give every new value its own name (a ROB entry) and they disappear. RAW is the program's own dataflow.","why":["","RAW is a true dependence: the value does not exist until its producer runs.","No hardware can remove RAW: the consumer needs the value.","A busy unit is a lack of hardware, not of names: renaming adds no divider."]},{"question":"Why does our core commit in order, when it executes out of order?","options":["So the register file always holds the state of a prefix of the program, and a mispredicted path can be thrown away","Because the register file has only one write port","Because results arrive in order anyway","To save the cost of the result buses"],"answer":0,"explain":"Values wait in the ROB until every older instruction has committed. When a branch turns out mispredicted, everything younger is still uncommitted and is simply dropped.","why":["","It has two write ports, one per committing instruction.","They do not: a load can finish after a younger add.","The result buses serve execution, not commit."]}],
  "multicore": [{"question":"Both cores request the memory port in every cycle. How many grants does core 1 get in 10 cycles?","options":["5","0: core 0 has priority","10"],"answer":0,"explain":"Round robin: whoever holds the priority bit wins a contested cycle, and the bit flips, so the grants alternate.","why":["","That is fixed priority, which can starve a core. Round robin flips the priority bit after every contested grant.","One port means one grant per cycle, shared by the two cores."]},{"question":"In the race, every <code>lw</code> and <code>sw</code> is atomic, yet half the increments are lost. Why?","options":["Core 1 loads the counter before core 0 has stored its increment, so both store the same value","The arbiter drops one of two simultaneous stores","Core 1 reads a stale copy from its cache"],"answer":0,"explain":"Core 1 runs one cycle behind: its load comes between core 0's load and store. Both add 1 to the same old value, and two increments make +1.","why":["","Losing arbitration delays an access by a cycle; it never discards one.","The dual-core of this step has no caches: both cores read the one shared memory, and the value is stale only because the other core's store comes later."]},{"question":"A core reads a block no other cache holds, then writes it. How many bus transactions under MSI, and under MESI?","options":["2 and 1","1 and 1","2 and 2","1 and 0"],"answer":0,"explain":"Both protocols fetch the block on the read miss. MSI leaves it Shared, so the write must broadcast an upgrade; MESI leaves it Exclusive, and the write moves it to Modified silently.","why":["","Under MSI the read leaves the block Shared, so the write must broadcast an invalidation first.","MESI's Exclusive state exists for exactly this case: E to M needs no bus.","The read miss still fetches the block over the bus, in either protocol."]},{"question":"A program spends 90 % of its time in work that parallelizes perfectly. What speed-up do 8 cores give, and what is the most any number of cores can give?","options":["About 4.7×, at most 10×","7.2×, at most 9×","8×, with no limit","About 4.7×, with no limit"],"answer":0,"explain":"Amdahl: 1 / ((1 − p) + p / n) = 1 / (0.1 + 0.9 / 8) = 1 / 0.2125 ≈ 4.7. As n grows, p / n vanishes and the serial 10 % remains: 1 / 0.1 = 10×.","why":["","7.2 is 0.9 × 8: it drops the serial tenth, which runs at one core's speed whatever n is. And the ceiling is 1 / 0.1 = 10, not 9.","Only the parallel 90 % shrinks with more cores; the serial 10 % takes as long as ever.","The serial 10 % never shrinks: even with infinitely many cores the run takes a tenth of the original time, so 10× is the ceiling."]}],
  "silicon": [{"question":"An unbuffered wire is made twice as long. Its delay grows about:","options":["4×","2×","Not at all: only gates have delay"],"answer":0,"explain":"Resistance and capacitance both grow with the length, and the delay goes with their product. That is why long wires get buffers.","why":["","Resistance and capacitance both double, and the delay goes with their product, not with either alone.","On a modern chip wires dominate delay. Counting NAND delays leaves them out, which is why timing is redone after routing."]},{"question":"What does technology mapping decide?","options":["Which library cells implement each piece of logic, cheapest first","Where each cell sits on the die","Which metal tracks each net uses","Which mask layers the fab needs"],"answer":0,"explain":"Mapping is the last step of synthesis: it covers the logic netlist with library cells. Placement, routing and masks come after.","why":["","That is placement, which comes after synthesis.","That is routing, after placement.","The masks follow from the finished layout; mapping works on the logic netlist."]},{"question":"At D₀ = 0.1 defects/cm², a die grows from 100 mm² to 200 mm². Its cost per good die rises by about:","options":["2.2×","2×","4×"],"answer":0,"explain":"Twice the area per die, and the yield falls from e<sup>−0.1</sup> = 90 % to e<sup>−0.2</sup> = 82 %: 2 × 0.905 / 0.819 ≈ 2.2.","why":["","That counts the area only. The bigger die also yields less, 82 % instead of 90 %, so each good one costs more.","Cost grows faster than area, but not as its square at this defect density: 2 × 0.905 / 0.819 ≈ 2.2."]}],
  "verify": [{"question":"A pipelined CPU and its golden model agree on every final register after a random program. What has that shown?","options":["That the CPU and the model agree on this program; both could share the same misreading of the specification","That the CPU implements RISC-V correctly","That every hazard combination has been exercised"],"answer":0,"explain":"An oracle written by the same people can be wrong the same way. That is why the official tests and an independent model (Spike) check the golden model too.","why":["","Only as correctly as the model: a shared misreading passes every comparison.","Coverage says what happened; one program reaches a small part of the combinations."]},{"question":"A test set reaches 100 % stuck-at fault coverage. What does it not catch?","options":["Defects that are not stuck-at faults: a gate that is too slow, a short between two nets","Any defect at all","Nothing: 100 % means every defect"],"answer":0,"explain":"Coverage is measured against a model. A slow gate (a transition fault), a bridge between nets or a defect that only shows at speed needs other tests.","why":["","It catches every defect that behaves like a stuck-at, which is most of them.","The percentage is of the modelled faults, not of every possible defect."]},{"question":"Why does a scan chain make a sequential circuit easy to test?","options":["The tester sets every flip-flop directly and reads every one back, so only the logic between them is left to test","It removes the flip-flops during test","It runs the circuit faster"],"answer":0,"explain":"With se = 1 the flip-flops form a shift register from scan-in to scan-out: any state can be loaded in n clocks and any state read out. What remains is combinational, and ATPG handles that.","why":["","They stay: they become a shift register while se = 1.","Scan shifts are usually slower than the functional clock."]}],
  "sidechan": [{"question":"The golden model and the out-of-order core agree on every register after every instruction of the attack. How did the secret get out?","options":["Through which cache line the wrong path filled, read back by timing","Through a register the flush forgot to restore","Through a store the wrong path made to memory","Through the branch predictor's table"],"answer":0,"explain":"Nothing architectural leaked: the registers and memory are right. The wrong path loaded a probe line chosen by the secret, the flush did not unload it, and the attacker found it by timing reloads.","why":["","The flush restores every register: that is why the golden model agrees.","A wrong-path store never reaches memory (in our model, or any real core).","The predictor is what let the wrong path run; the secret goes through the cache."]},{"question":"Why does masking the index stop the attack?","options":["The load's address now waits for len, so the wrong path cannot load out of bounds before the flush","The mask stops the branch from being predicted","The mask flushes the cache","The mask makes the load slower than a miss"],"answer":0,"explain":"The address is x AND (x < len ? all ones : 0). Until len arrives, the AND cannot run, nor the loads after it; by then the branch has resolved and the wrong path is gone.","why":["","The branch is still predicted, and still mispredicted; it just has nothing to leak through.","Nothing is flushed: the probe lines are simply never touched.","The load is not slower; it cannot start until its address is known."]},{"question":"Fill-at-commit cost the ooo chapter's benchmarks nothing on our model. Why is that not proof it is free?","options":["Their data was written before it was read, so their loads hit anyway; a program whose loads miss pays","The benchmarks have no branches","The benchmarks run on the in-order core","Fill-at-commit only applies to stores"],"answer":0,"explain":"Each benchmark writes its data and then reads it, and a store fills its line, so no load misses. Summing a 4 KB array, four times the cache, does miss, and there fill-at-commit costs cycles.","why":["","They are full of branches and mispredictions.","The same out-of-order model ran them.","It is about loads: a store fills its line at commit anyway."]}],
  "lanes": [{"question":"Why does saxpy on the lane core take 134 cycles for 74 instructions?","options":["Its 20 loads and stores take 4 cycles each, one per active lane","Every instruction takes about two cycles","The loop branch flushes instructions each iteration","The lanes wait for each other at the end of the loop"],"answer":0,"explain":"20 memory instructions × 4 cycles = 80, plus the other 54 at one cycle each: 134. The sequencer serves one lane per cycle and holds the PC meanwhile.","why":["","Only memory instructions take more than one cycle; the other 54 take one each.","The front end is the single-cycle CPU's: a branch is decided in the cycle it executes, and nothing is flushed.","The lanes run in lock-step on one PC: there is nothing to wait for at the end of the loop."]},{"question":"How does lane 2 of a lane core know that it is lane 2?","options":["<code>csrr t0, tid</code> reads a constant wired into that lane","It reads its own PC, which differs per lane","The program ROM holds a copy of the kernel per lane","Its register file starts out holding its number"],"answer":0,"explain":"Every lane receives the same instruction; only the tid constant wired into each (0, 1, 2, 3) differs, and the kernel turns it into the elements that lane handles.","why":["","There is one PC for all lanes: that is what makes it a lane core.","There is one program ROM, and one instruction a cycle for every lane.","All lanes' registers start out alike; the wired tid constant is the only difference."]},{"question":"<code>blt t3, t2, loop</code> runs with all four lanes active. Whose comparison steers the PC?","options":["Lane 0's, the leader: the lowest active lane","Lane 3's, the highest","A majority vote of the four","All four must agree, or the core stops"],"answer":0,"explain":"A lowest-set-bit circuit turns the lane enable bits into a one-hot word, and one-hot multiplexers bring that lane's ALU flags to the next-PC logic.","why":["","The leader is the lowest active lane, not the highest.","There is no voting logic: one-hot multiplexers pass exactly one lane's flags.","This core does not check that the lanes agree: when they disagree it follows the leader, which is wrong for the others."]}],
  "simt": [{"question":"At power-on every flip-flop is 0. Why are all four lanes active?","options":["The mask register stores the mask inverted","Every kernel starts with a <code>tmc</code>","The leader turns the other lanes on","A reset pin sets every mask bit"],"answer":0,"explain":"A stored 0 means \"active\", so the all-zero power-on state is the full mask, with no reset logic.","why":["","No instruction is needed: the first instruction already runs on every lane.","The leader steers branches and supplies operands; it sets no mask bits.","The core has no reset pin: power-on zeroes the flip-flops, and the inverted storage turns that into all ones."]},{"question":"Lanes 0–3 reach <code>split t1</code> with t1 = 0, 5, 0, 7. What runs first, and what is pushed?","options":["Lanes 1 and 3; an entry with mask 1111, else lanes 0 and 2, the resume PC, pending set","Lanes 0 and 2, the leader's side","All four: split only marks the branch","Lanes 1 and 3; an entry holding only the resume PC"],"answer":0,"explain":"Lanes with t1 ≠ 0 go first; the entry remembers the mask to restore, the lanes to run next, where they resume, and that they are still pending.","why":["","split does not follow the leader: the lanes with t1 ≠ 0 go first, whichever lane leads.","split changes the mask at once: the waiting lanes are off until the first join.","Without the old mask and the waiting lanes, join could neither switch sides nor bring the warp back together."]},{"question":"A kernel nests five ifs, each with its own split. What happens on this core?","options":["The fifth split loses the bottom stack entry","The stack spills into data memory","The fifth split is ignored and its if runs on every lane","The core waits until a join frees an entry"],"answer":0,"explain":"The stack is four entries in a shift register: a push shifts everything down, and the bottom entry falls off. The instruction-set simulator stops with a stack overflow instead.","why":["","The stack is four entries of flip-flops; nothing connects it to memory.","The split still pushes, and the shift register drops its bottom entry.","Nothing in the hardware waits for a free entry."]}],
  "warps": [{"question":"One warp, 8-cycle loads. Why does saxpy's second <code>lw</code> issue right behind the first?","options":["It reads no pending register and writes another one, so the scoreboard lets it go","Loads skip the scoreboard check","The memory has a second port for it","It goes to a faster memory"],"answer":0,"explain":"The scoreboard only stops an instruction whose rs1, rs2 or rd is pending. The two loads are independent, so both are in flight at once and the warp stops only at the first use.","why":["","A load is checked like any instruction, rd included: it must not overwrite a register another load is about to fill.","Ports are not the limit: one request enters the memory pipeline every cycle. The memory is slow, not busy.","Every load in this chapter's core takes 8 cycles; a faster shared memory comes in the next chapter."]},{"question":"What does a second resident warp add to the core?","options":["A slot (PC, mask, stack, running bit, scoreboard), a register bank in every lane and a read of the program ROM","A second decoder, ALUs and memory","Only a PC","Four more ALUs, so two warps issue at once"],"answer":0,"explain":"Only state is copied, plus what reads it: 110 715 NANDs, of which 92 564 are the new register banks.","why":["","The decoder, the ALUs and the memory are shared; only one warp issues per cycle.","Each thread's registers must survive while the other warp runs: the register banks are most of the cost.","One warp issues per cycle, so the lanes' ALUs are shared by all warps."]},{"question":"A GPU has 65 536 registers per streaming multiprocessor. A kernel needs 64 registers per thread. How many threads fit?","options":["1024","2048","512","65 536"],"answer":0,"explain":"65 536 / 64 = 1024 threads, 32 warps of 32: half the 2048 that fit at 32 registers a thread.","why":["","That is at 32 registers a thread.","That would be 128 registers a thread.","That counts registers, not threads."]}],
  "feed": [{"question":"Lanes 0–3 load global words 0, 4, 8 and 12. How many accesses?","options":["4","1","2","3"],"answer":0,"explain":"A line is four words, so the four words sit in lines 0, 1, 2 and 3: one access each. That is the by-rows layout.","why":["","One access serves only the lanes on the leader's line, and these addresses are 16 bytes apart.","Two accesses would need pairs of lanes on one line; here every line holds one of the four words.","Every lane is on a line of its own, so none can go along with another."]},{"question":"Four lanes read shared-memory word 3, all of them. How many accesses?","options":["1: the word is broadcast","4: they are all in bank 3","2","0: shared memory is a cache"],"answer":0,"explain":"Lanes asking for the same word share it. A conflict needs two different words in one bank.","why":["","One bank, but one word: a conflict needs two different rows of the same bank.","There is one word to fetch, and one access serves every lane that asked for it.","Shared memory is a scratchpad the threads address explicitly: every load is an access."]},{"question":"The tiled matrix multiply makes 40 global accesses instead of 144. Why does it still lose on this core?","options":["It runs 560 instructions instead of 396, and this memory takes a line every cycle","Its barriers serialize the warps for good","Shared memory is slower than global memory here","Its bank conflicts cost more than the accesses saved"],"answer":0,"explain":"A global access costs the issue port no more than a shared one, and four warps hide the 8-cycle latency, so fewer accesses save nothing while the extra instructions cost cycles: 592 against 396.","why":["","The barriers cost waiting, but the kernel loses because of its instruction count; with a slow enough memory the same barriers pay.","Shared loads take 2 cycles against 8: shared memory is the faster one.","A row of the A tile is one word for the whole warp, and a column of the B tile spans the four banks."]}],
  "pixels": [{"question":"Swap is pressed mid-frame with \"wait for vsync\" off. What does the screen show?","options":["The top of one picture and the bottom of the other: tearing","A black frame","Nothing changes until the copy is done","The frame from two swaps back"],"answer":0,"explain":"The scan-out keeps reading word by word; the swap moves its address multiplexers at once, so the rest of the frame comes from the other buffer.","why":["","The scan-out never stops sending pixels; it only switches buffers part-way.","Nothing is copied: the swap moves two address multiplexers, so it takes effect at once.","A swap shows the frame just drawn, not an older one."]},{"question":"Why does depth set-up cost more than the rest of the rasterizer?","options":["Its slopes divide by twice the area: two runs of a 30-bit divider, 32 cycles each","Depth values are 32 bits wide","The depth buffer is cleared for every triangle","Every pixel needs a multiplication for z"],"answer":0,"explain":"Z<sub>x</sub> and Z<sub>y</sub> are quotients by 2·area: four products, two divisions and ten shift-and-add steps, about 80 cycles that start during the edge set-up, so 76 more cycles before the walk; 12 032 NANDs. Per pixel z is one add.","why":["","Width costs adders, not cycles; the time goes into the two divisions.","The depth buffer is cleared once a frame, not per triangle.","z is linear like the edges: one add per pixel step, no multiplication."]},{"question":"Depth test on. A translucent triangle is drawn first, then an opaque one behind it. What goes wrong where they overlap?","options":["The opaque one fails the depth test there, and the translucent one was blended over the old background","Nothing: the depth test sorts it out","The opaque one overwrites the translucent one","The overlap is blended twice"],"answer":0,"explain":"The translucent pixels wrote their depth, so the surface behind fails \"nearer\"; the blend had already mixed with whatever was in the frame. Hence opaque first, translucent back to front.","why":["","The depth test picks which pixel survives; it cannot redo a blend that mixed with the wrong colour.","It is behind, so the depth test rejects it where they overlap.","The opaque pixels are rejected, so there is no second blend: the problem is the first one."]}],
  "graphics": [{"question":"Why is the vertex buffer double-buffered?","options":["So the kernel computes frame f + 1 while the command unit reads frame f's vertices","Because a vertex takes two words","To make room for the triangle's fourth vertex","Because the scan-out reads it"],"answer":0,"explain":"Buffer f mod 2 holds frame f. The kernel launched at the start of a frame writes the other buffer, so it never overwrites vertices the command unit is still reading.","why":["","A vertex is one packed word: X | Y << 8 | Z << 16.","The fourth vertex pads the vertex count to a multiple of the lane count; it sits in the same buffer.","The scan-out reads the framebuffer; vertices reach the rasterizer through the command unit."]},{"question":"With the pixel-a-cycle clear, the cube's frames took 7168 to 8192 cycles. Why always a multiple of 1024?","options":["A frame ends at a flip, and flips happen only at vsync, once per 1024-cycle scan-out","The rasterizer works in blocks of 1024 pixels","The clear takes 1024 cycles","The vertex kernel runs once every 1024 cycles"],"answer":0,"explain":"Whatever the drawing takes, the frame waits for the next vsync to flip: 7168 = 7 × 1024, 8192 = 8 × 1024.","why":["","The rasterizer walks 4 × 4 tiles, one pixel a cycle, for as long as the triangle needs.","That clear took 4438 cycles, not a multiple of 1024.","The kernel runs once a frame (109 cycles for the cube), hidden in the clear."]},{"question":"How long does the rasterizer spend on a cube face that points away?","options":["Three set-up cycles: twice its area is negative","Nothing: the command unit skips it","Its whole 85-cycle set-up","One cycle per pixel it would have covered"],"answer":0,"explain":"Set-up computes twice the area first; a negative sign culls the triangle after three cycles, before the depth division and before any tile.","why":["","The command unit sends every triangle; the rasterizer's set-up decides to cull.","Set-up stops at the area's sign, before the depth division.","Culling happens before any tile is walked: no pixel is visited."]}],
  "dram": [{"question":"Hang twice as many cells on each bit line, so it is 200 fF instead of 100. How far does a stored 1 now move it?","options":["61 mV","110 mV","55 mV","220 mV"],"answer":0,"explain":"ΔV = 0.55 V · 25 / (25 + 200) = 61 mV. Still above the 15 mV offset, but the margin shrinks: that is the limit on how many cells a bit line can amortize its amplifier over.","why":["","The cell's charge is now shared with twice the capacitance, so the line moves less.","Halving would hold if ΔV went as 1 / Cb. It goes as Cs / (Cs + Cb), and the cell's own 25 fF stays in the sum.","More capacitance on the line takes more charge to move it: the swing falls, it cannot grow."]},{"question":"After an activate, why must the whole row be written back, and what does it?","options":["Every cell of the row shared its charge with its bit line; the sense amplifiers restore them all while the word line is still up","The column select drained the one cell it read; the controller rewrites that word","The read heated the cells and they leak faster; the next refresh restores them","Only cells holding 1 lost charge; the write driver puts it back"],"answer":0,"explain":"The word line joins every cell of the row to its bit line at once, so every cell is left near VDD/2. Each column's amplifier swings its bit line to a rail, and the cell, still connected, follows: the read is its own write-back.","why":["","The damage is done before any column is selected: raising the word line shares the charge of every cell in the row.","Leakage has nothing to do with it. Charge sharing moved the cells to the bit lines' level, and waiting for refresh would lose them.","A stored 0 is pulled up towards VDD/2 just as a 1 is pulled down. The amplifiers restore both, and the write driver only acts on a write."]},{"question":"Here a row hit costs 8 cycles and a miss 12. What does the miss pay for that the hit does not?","options":["tRCD: the activate, word line and sensing before the column command","tRP: the precharge","tCAS: the column path","tRFC: a refresh"],"answer":0,"explain":"A closed bank must first open the row: ACT, then tRCD = 4 cycles before the column command. 12 − 8 = 4. A conflict adds tRP on top: 16.","why":["","A precharge is needed only when another row is open in the bank: that is the conflict.","Every access pays tCAS, the hit included.","A refresh delays a request only when one falls in its way; it is not part of a miss."]}],
  "memctrl": [{"question":"Open page. Bank 0 has row 3 open, and the cache asks for a line in row 5 of bank 0. Which commands does the controller issue?","options":["PRE, ACT, RD","ACT, RD","RD","PREA, REF, ACT, RD"],"answer":0,"explain":"A conflict: close row 3 (PRE, then tRP), open row 5 (ACT, then tRCD), read (RD, tCAS, then the burst): 16 cycles.","why":["","An ACT on a bank whose row is still open breaks the rules: the amplifiers hold row 3 and must be precharged first.","RD alone serves the open row, row 3. That is a hit, and this request wants row 5.","PREA and REF are the refresh sequence. A conflict closes only its own bank and refreshes nothing."]},{"question":"A request arrives just after the controller has started a refresh. Its row was open before. What does it pay?","options":["The rest of the refresh, then a miss: PREA closed every bank","The rest of the refresh, then a hit: its row is still open","A hit at once: the refresh is postponed while a request waits","Nothing extra, but its data is X: the device was busy"],"answer":0,"explain":"The refresh precharged every bank, then the device takes no command for tRFC. Then the request opens its row again: a miss. In all up to 105 cycles.","why":["","A REF needs every bank precharged first: no row survives it.","DDR4 allows postponing up to 8 refreshes, but this controller never does: once due, a refresh goes first at the next idle cycle.","The controller holds the request until the device may take commands again. The controller breaks no timing rule, so the device has nothing to flag."]},{"question":"The copy (source word i, destination word i + 1024, rows of 16 words) on 4 banks with the plain mapping. Do its streams still fight?","options":["Yes: 1024 words is a whole number of 4 × 16-word stripes, so each destination line still lands in its source line's bank","No: with four banks two streams never share one","No: the destination now lands in the next bank","Only for its writes"],"answer":0,"explain":"1024 words is a whole number of 4 × 16-word stripes: 1024 / (4 × 16) = 16: the destination is the same bank, 16 rows down. More banks only help when the bank bits differ; the explorer shows the copy's row hits barely move. The XOR hash is what separates them.","why":["","Which bank a line uses depends on its address bits. Two addresses that agree in the bank bits share a bank however many banks there are.","The bank bits of i and i + 1024 are the same: 1024 changes only row bits.","Reads and writes are both line requests to the same banks: the fill of a source line and the write-back of a destination line conflict alike."]}],
  "flash": [{"question":"A row holds 1100. You program it with data 1010 and do not erase. What does it hold?","options":["1000","1010","1110","0110"],"answer":0,"explain":"A program can only clear bits, so the result is the AND of the two: 1100 AND 1010 = 1000. Writing 1010 for real needs an erase of the block first.","why":["","Bit 1 is 0 in the row and 1 in the data. A program cannot raise a bit: only an erase can.","That is the OR. A program adds charge, which can only turn 1s into 0s.","That is the XOR. Flash has no toggle: a programmed bit stays 0 until its block is erased."]},{"question":"Why does a NAND cell take about 4 F² where a NOR cell takes about 10?","options":["Its cells sit in series and share one contact at each end of the string; a NOR cell needs a bit-line contact of its own or shared with one neighbour","A NAND cell is a smaller transistor","A NAND cell stores two bits","NAND needs no sense amplifiers"],"answer":0,"explain":"The contacts, not the transistors, set the pitch. A string of eight here (128 or more in real chips) pays for two contacts in all.","why":["","The cell is the same floating-gate transistor in both arrays. The difference is the wiring.","Both arrays here store one bit a cell (SLC). Several bits a cell is a separate trick, open to either.","Every bit line still needs a sense circuit. What NAND saves is a contact per cell."]},{"question":"Garbage collection takes a block of 8 pages, 6 of them still valid. Counting the host writes that then fill the freed pages, what is the write amplification?","options":["4","3","1.33","0.75"],"answer":0,"explain":"The block frees 8 − 6 = 2 pages for 6 copies. Two host writes then cost 2 + 6 = 8 page programs: 8 / 2 = 4.","why":["","That is copies per freed page. The host's own write into each freed page is a program too.","That is 8 / 6, pages per valid page: no measure of extra programs.","That is the fraction of the block still valid. Write amplification is programs divided by host writes."]}],
  "bus": [{"question":"A sender raises valid in cycle 1; the receiver raises ready in cycle 3. When does the transfer happen?","options":["At the rising edge that ends cycle 3, the first where both are 1","At the edge that ends cycle 1: valid is enough","The moment ready rises, inside cycle 3","Never: the sender must drop valid and try again"],"answer":0,"explain":"Both signals are sampled at the rising edge, and the transfer is the edge where both are 1. Meanwhile the sender holds valid and its data steady.","why":["","Valid only says the data is there. Without ready the receiver may not be able to take it.","Nothing on the bus happens between edges: the handshake is synchronous, sampled at the rising edge.","Once raised, valid stays up until the transfer. Dropping it would let a polite pair miss each other for ever."]},{"question":"The DMA engine is waiting for a page read from the flash. The CPU wants a word of RAM, which is idle. What happens on this interconnect?","options":["The CPU waits: the grant stays with the DMA until the flash answers","The arbiter takes the bus from the DMA, round robin","The CPU reaches RAM at the same time, through another path","The CPU's read is dropped and must be retried"],"answer":0,"explain":"One transaction at a time: the grant is held until that transaction's response, here up to a 64-cycle page read. Split transactions or a crossbar would let the CPU through.","why":["","Round robin decides who goes next, between transactions. It never takes the bus back in the middle of one.","That is a crossbar. This interconnect has one path, shared by both masters.","The CPU's valid simply stays up: a handshake never loses a request, it only waits."]},{"question":"The CPU sets up the DMA engine with four stores and lets it copy 16 words from RAM to RAM. How many bus transactions in all?","options":["36","32","20","16"],"answer":0,"explain":"Four register writes from the CPU, then a read and a write for every word: 4 + 2 × 16 = 36. (Clearing the interrupt afterwards is one more store.)","why":["","That is the copy alone. The four setup stores go over the bus too: the DMA's registers are a slave at 0x4000_0000.","That counts one transaction a word. The DMA reads each word into a register, then writes it: two.","That is one per word, and no setup. Each word is a read and a write."]},{"question":"Give the CPU a write-back data cache. It fills a buffer with stores, then starts the DMA to copy the buffer to a device. The device receives old data. What was missing?","options":["Cleaning the buffer's dirty lines to RAM (and a fence) before the store that starts the DMA","Invalidating the buffer's lines after the DMA finishes","A wait state on the DMA's reads","Nothing: the arbiter orders the CPU's stores before the DMA's reads"],"answer":0,"explain":"The new data sat in dirty lines; the DMA reads RAM, which still held the old. Before a transfer out of memory the driver writes the lines back (clean) and fences, so the data is in RAM before the MMIO store that kicks the engine. Before a transfer into memory the driver invalidates the buffer's lines, so no dirty line can later be evicted over the incoming data; after it, on a CPU that speculates or prefetches, it invalidates again, so the CPU does not read a line refilled meanwhile. A coherent interconnect snoops the DMA's accesses and makes both automatic.","why":["","Invalidating is for the other direction, a DMA writing RAM. Here the stale copy is in RAM, and invalidating would throw the new data away.","Timing is not the problem: however slowly the DMA reads, RAM holds the old words until the cache writes them back.","The arbiter orders bus transactions. Stores that hit in a write-back cache never reach the bus until their lines are evicted or cleaned."]}],
  "message": [{"question":"A 1 KB message goes 5600 km at 1 Gb/s. You buy a link a thousand times faster. Roughly how much sooner does it arrive?","options":["Hardly at all: about 28 ms either way, because nearly all of it was travelling","A thousand times sooner","About twice as soon","It arrives later, because a faster link is more sensitive"],"answer":0,"explain":"Pushing was 8 µs and travelling 28 ms. The rate only touches the first.","why":["","That would be true only if all of the delay were pushing.","Nothing in the sum halves: one part shrinks to almost nothing, and it was almost nothing already.","A faster link does not slow anything down."]},{"question":"Why is a message cut into packets rather than sent whole?","options":["A line can be shared packet by packet, and a wrong bit costs one packet instead of the whole message","Packets travel faster along the wire than a long message","A long message would be too heavy for the wire","Headers make the data smaller"],"answer":0,"explain":"With one bit in a million wrong, a 1 MB message sent whole almost never arrives clean; cut into 1000-byte packets it costs 1.05 MB in all.","why":["","Every bit travels at the same speed, in a packet or not.","A wire has no limit of that kind; what it has is other users and errors.","Headers add bytes."]},{"question":"An amplifier of +20 dB, a cable of −60 dB and an amplifier of +30 dB, in a row. What does the chain do to the power?","options":["Divides it by 10: the sum is −10 dB","Multiplies it by 36 000: 20 × 60 × 30","Nothing: the amplifiers make up for the cable","Divides it by 60"],"answer":0,"explain":"Decibels add: 20 − 60 + 30 = −10 dB, a ratio of 0.1.","why":["","Decibels are already logarithms, so they add. Multiplying them has no meaning.","The amplifiers add 50 dB and the cable takes 60.","That treats −60 dB as a ratio of 60. It is a ratio of a million."]}],
  "telegraph": [{"question":"A main-line sounder needs 38.0 mA in its 120 Ω coil. The 24 V battery drives an 80 km iron line. What happens?","options":["The sounder never moves: the current falls short","It moves: 24 V is far above the coil's pull-in voltage","It moves, slowly"],"answer":0,"explain":"The wire is 637 Ω, so the loop current is 31.7 mA against 38.0 mA. The coil needs a current, not a voltage: the line's resistance eats the battery.","why":["","The pull-in voltage is across the coil alone. The wire takes most of the 24 V first: the coil sees 3.8 V.","Below its pull-in current the armature does not move at all; a weak pull is not a slow one."]},{"question":"A modem sends 16 levels at 2 400 baud. What bit rate is that, and which limit says how much bandwidth it needs?","options":["9.6 kb/s; Nyquist, at least 1.2 kHz","2.4 kb/s; Shannon","38.4 kb/s; Nyquist, at least 4.8 kHz"],"answer":0,"explain":"Four bits a symbol: 2 400 × 4 = 9 600 b/s. Nyquist bounds the symbol rate by 2B, so B ≥ 1 200 Hz. Shannon adds the SNR that 16 levels need: 24.1 dB.","why":["","Baud counts symbols, not bits. Each of 16 levels carries log<sub>2</sub> 16 = 4 bits.","That multiplies by 16 instead of by log<sub>2</sub> 16, and 2B ≥ 2 400 gives 1.2 kHz, not 4.8."]},{"question":"A line of 3100 Hz and 30 dB SNR. Shannon's limit is about:","options":["30.9 kb/s, whatever the modulation","6.2 kb/s, the Nyquist rate","Unbounded: add levels"],"answer":0,"explain":"3100 × log<sub>2</sub>(1 + 1000) = 30.9 kb/s. More levels run into the noise: the symbols blur together.","why":["","Two levels give 2B log<sub>2</sub> 2 = 2B only if the noise lets two levels through; the limit here is higher, because 30 dB supports many more.","Past √(1 + SNR) levels the symbols overlap in noise, and the errors cost more than the extra bits gain."]}],
  "exchange": [{"question":"A caller dials 5. How many times does the pulse relay in the exchange operate and release, and what does the counter hold afterwards?","options":["5 times; the count is 5 on the falling edge of the fifth pulse","10 times; the count is 10","5 times; the count is 4, one lagging"],"answer":0,"explain":"The dial opens the loop five times; the pulse relay follows. Each pulse ends with a falling edge, the counter's clock: after the fifth, the counter holds 5.","why":["","Operate-and-release is one pulse. Counting both edges would give 10, but the counter advances only on the falling one.","The slave copies the master when the pulse falls, so the count is updated by then: nothing lags."]},{"question":"1000 subscribers, 2 calls an hour of 3 minutes each, offer 100 Erlangs. Are 1 000 trunks to another exchange needed?","options":["No: 117 give 1 % blocking","Yes: any caller might call out","No: 100 trunks suffice"],"answer":0,"explain":"Erlang B at 100 E and 1 % is 117 trunks: sharing works because most phones are idle at any moment. A trunk per phone would be 9 times more.","why":["","Any caller might, but not all at once. Trunks are sized for the busy hour, not for the number of subscribers.","100 Erlangs is the average number of calls up; calls arrive at random, so with exactly 100 trunks about 8 % of them would be blocked."]},{"question":"Why can a start-stop receiver tolerate a clock a few percent off, when two clocks that must stay in step over a long stream cannot?","options":["It only has to stay right for one character, since each start edge resets it","Its clock is more accurate","Start-stop codes carry the clock in the data"],"answer":0,"explain":"Between two start edges it counts only 7.5 units. An error of e shifts the stop sample by about 6 e units, and the margin is half a unit.","why":["","Teleprinter motors were governed, not precise: the margin comes from the frame being short.","The data carries no clock; only the start edge, once a character, tells the receiver where to begin."]}],
  "wire": [{"question":"A driver of 387 Ω charges 1 pF. About how long until the node is halfway?","options":["ln 2 · 387 Ω · 1 pF = 268 ps","387 Ω · 1 pF = 387 ps","0.38 · 387 Ω · 1 pF = 147 ps"],"answer":0,"explain":"A lumped RC charges exponentially; the halfway point is ln 2 of the time constant. The factor 0.38 belongs to a wire whose resistance and capacitance are spread along it.","why":["","RC is the time constant: the node has reached 63 %, which is later than half.","0.38 applies to a distributed RC line. Here the capacitor sits at the driver's output."]},{"question":"A 4 mm and an 8 mm wire of the same metal, each with a driver strong enough that the driver term is negligible. How do their delays compare?","options":["The 8 mm wire is 4 times slower: delay grows with the square of the length","The 8 mm wire is 2 times slower","The same: both are limited by the driver"],"answer":0,"explain":"Doubling the length doubles both R and C, so 0.38 · R · C quadruples. Repeaters turn this into a linear growth.","why":["","That holds only when a driver's resistance dominates. A wire's own R and C both grow with length.","With a strong driver the wire's own RC is all that is left."]},{"question":"An open CMOS input at the end of a 15 cm trace is driven by a 10 Ω output. What does the far pin see first?","options":["Twice the launched wave: 3.00 V against 1.50 V, then ringing","The full 1.8 V swing, cleanly, after one flight time","Half the swing, until the wave returns"],"answer":0,"explain":"The line launches V·Z₀ / (Z₀ + Rs) = 1.50 V; an open end reflects it with Γ = +1, so the pin sees double. The driver's low resistance then reflects the echo with Γ = -0.67, and the pin rings.","why":["","A clean step needs the echo absorbed, which takes Rs ≈ Z₀ (series termination) or a matched far end.","Half the swing is what a series-terminated line shows at the driver. The open far end doubles the wave."]}],
  "clocks": [{"question":"A Schmitt trigger has thresholds 0.76 V and 1.04 V. A slow edge crosses 0.90 V with 0.05 V of noise on it. How many times does the output switch?","options":["Once: the noise never gets across the 270 mV between the thresholds","Several times, like a plain inverter","Zero: hysteresis blocks slow edges","Twice: once at each threshold"],"answer":0,"explain":"After the output has risen at the upper threshold the input would have to fall back below the lower one to switch it again. Noise of 0.05 V cannot move a signal 270 mV.","why":["","A plain inverter has one threshold, so noise that crosses it flips the output each time. The second threshold is what removes that.","The output does switch once the input has travelled to the far threshold: hysteresis delays the switch and does not forbid it.","The two thresholds apply to different directions: a rising edge meets only the upper one."]},{"question":"A 2-flop synchronizer works at 500 MHz. Which change gives the most MTBF?","options":["Halving the clock to 250 MHz","Halving the data rate","Replacing both flops with faster ones of half the clock-to-q","Doubling the data rate"],"answer":0,"explain":"The clock enters twice: e^(t_r/τ) grows with the period (t_r is a period less 6 NAND delays) and the denominator falls with fclk. Halving the data rate only halves the denominator.","why":["","It halves the event rate in the denominator, a factor of 2. The exponent is where the orders of magnitude are.","Clock-to-q is a small part of the budget, and it enters the exponent only as a subtraction from one period.","That makes the MTBF half as long."]},{"question":"The asynchronous FIFO shows empty = 0 on the read side. What can be said about the number of words in it?","options":["At least one: a flag that is low is true, one that is high may be late","Exactly one: empty would have gone low the moment the first word was written","Nothing: the pointers are in different clock domains","At most the depth"],"answer":0,"explain":"The read side sees a write pointer that is two edges old. Words written since are not counted yet, so empty can stay high with words inside. It goes low only when the old pointer already shows a word, and that word is still there.","why":["","Empty low says the old write pointer was past the read pointer, so at least one word; more may have arrived since, which the read side has not seen yet.","The sampled pointer is the old value or the new one, because it is a Gray code, so something is known.","True, but it says nothing about empty."]}],
  "uart": [{"question":"A receiver samples the middle of each bit, counting from the start edge. Its clock is 3 % slow. Is the stop bit read correctly, and why?","options":["Yes: the stop sample is 9½ bits after the start edge, 3 % of that is 0.29 bit, inside the half-bit margin","No: any error corrupts the last bit","Only if the divisor is odd","Yes, because the start bit resynchronizes the receiver at every bit"],"answer":0,"explain":"The error grows with the distance from the start edge. At the stop sample, 9.5 bit times in, 3 % is 0.285 bit, less than the 0.5 bit between the sample and the edge of its cell. The limits are 4.9 % (slow) and 5.6 % (fast).","why":["","The sample moves by a fraction of a bit that grows with k; it corrupts the bit only when it crosses a cell edge.","The divisor sets the rate, not where the samples fall inside a bit.","Only the start edge synchronizes the receiver; the later edges in the data are ignored."]},{"question":"rx is held low for 30 bit times. What does the receiver report?","options":["One frame of 0x00 with a framing error, then nothing until the line rises","Three frames of 0x00","Nothing: a long low is ignored","An overrun"],"answer":0,"explain":"The first start bit is confirmed, eight zero data bits are shifted in, and the stop sample reads 0: a framing error. Instead of seeing another start at once, the receiver waits for the line to go high, so a break is one event.","why":["","A receiver that returned to idle after the error would see the still-low line as a new start every frame. This one waits for a 1.","The first low is a valid start bit: it is still low in the middle of the bit.","Overrun needs a good byte arriving while the receive FIFO is full; here no byte is stored at all."]},{"question":"At 115 200 baud a 16-byte receive FIFO raises its interrupt at 8 bytes. How long does the CPU have before the next byte is lost?","options":["About 694 µs, eight byte times","87 µs, one byte time","1389 µs, the whole FIFO","It depends on the CPU clock"],"answer":0,"explain":"Eight bytes are in the FIFO when the interrupt starts, eight places are free, and a byte takes 86.8 µs on the wire: 694 µs. The CPU clock only decides how many instructions fit in that time.","why":["","That would be the deadline without a FIFO, which is the reason to have one.","The FIFO is already half full when the interrupt starts, so only the free half counts.","The deadline is in time on the wire, which the baud rate fixes; the clock converts it to cycles."]}],
  "spi": [{"question":"A mode 0 device (CPOL 0, CPHA 0) is wired to a master in mode 1 (CPOL 0, CPHA 1). What goes wrong?","options":["The master changes MOSI on the edge the device samples on: every bit is read half a period early or late","Nothing: both idle low and sample on a rising edge","Only the clock polarity differs, so the bytes arrive inverted","The device cannot be selected"],"answer":0,"explain":"Both idle low, but mode 0 samples on the first (rising) edge and changes data on the falling one, while mode 1 uses that first rising edge to change the data and samples on the falling edge. The device reads the line at the moment the master is changing it.","why":["","The idle level is the same, but the first edge means something different to each end: that is the whole content of CPHA.","CPOL is the same here. Inversion would need an inverter on the data, not a different clock phase.","Selection is the chip select, which does not depend on the mode."]},{"question":"A 3.3 V I²C bus has 200 pF of wiring and runs Fast-mode (300 ns rise time, 3 mA sink). Which pull-up is legal?","options":["1369 Ω","100 Ω","10 kΩ","4.7 kΩ"],"answer":0,"explain":"Rp must be at least (3.3 − 0.4) / 3 mA = 967 Ω so the pad can hold the wire at 0.4 V, and at most 300 ns / (0.8473 · 200 pF) = 1770 Ω so it rises in time. 1369 Ω is inside the window.","why":["","A 100 Ω pull-up would make the pad sink 29 mA: far over the 3 mA limit, and the low level would not reach 0.4 V.","10 kΩ rises in 1695 ns, over the 300 ns limit.","4.7 kΩ gives 796 ns, still over 300 ns."]},{"question":"Controllers A and B start together, sending the 7-bit addresses 0x50 and 0x52. Which loses, and in which bit?","options":["B, in address bit A1: it released the wire where the other pulled it low","A, in bit A6: the lower address always loses","Both, and they must retry","Neither: both frames are corrupted"],"answer":0,"explain":"0x50 is 1010000 and 0x52 is 1010010: they first differ at A1. B sends a 1 (lets go), reads 0 (the other is pulling) and gives up; the other controller reads exactly the bit it sent and goes on. The lower address wins because it pulls low first.","why":["","The first differing bit decides, and it is not A6 here. The lower address does win, but because of the bit where the two first differ.","Only the one that reads back a different value than it sent gives up. The winner is unharmed.","The wire carries the AND of the two bits, which is the winner's bit: no bit is corrupted."]}],
  "signals": [{"question":"A pulse is made four times shorter. What happens to the band it occupies?","options":["About four times wider: band × width stays about constant","Four times narrower: less signal, less band","Unchanged: the band depends on the amplitude","Sixteen times wider: it goes as the square"],"answer":0,"explain":"Sharper features in time need higher frequencies to build them. That constant product is why a faster link needs a wider channel.","why":["","A short pulse has less energy, but spread over more frequencies.","Amplitude scales every frequency alike and moves no energy between them.","The relation is proportional, not quadratic."]},{"question":"A 7 kHz tone reaches a converter sampling at 10 kHz with no filter in front. What comes out?","options":["Samples of a 3 kHz tone, indistinguishable from a real one","Nothing: the tone is above the band","A 7 kHz tone, with more error","A 17 kHz tone"],"answer":0,"explain":"It folds about 5 kHz: 10 − 7 = 3. The samples are exactly those of a 3 kHz tone, so the digital side cannot remove it afterwards.","why":["","Sampling removes nothing. That is what makes aliasing dangerous.","No 7 kHz tone can be represented at this rate.","A sampled signal only holds frequencies up to half the rate."]},{"question":"Why does the FIR filter in gates need no multiplier?","options":["Its taps are small powers of two and sums of them: multiplying by 4 is wiring, and 6 is 4 + 2","Multipliers cannot run at the sample rate","Its adders multiply when given a carry","It only handles 1-bit samples"],"answer":0,"explain":"Fixed taps can be chosen to be cheap. A general filter with programmable taps needs real multipliers, each 632 NANDs at 8 × 8.","why":["","They can, with a long enough clock period: this is about cost.","A carry adds one; it does not scale a word.","The samples are 8 bits, and the output 12."]}],
  "noise": [{"question":"A receiver has a 20 MHz channel and a noise figure of 6 dB. What is its noise floor?","options":["About −95 dBm: −174 + 73 + 6","About −174 dBm: the density is the floor","About −168 dBm: −174 + 6","About −101 dBm: it leaves out the noise figure"],"answer":0,"explain":"10 log₁₀(20 × 10⁶) is 73 dB. The density is per hertz, so the band adds; the receiver's own noise adds on top.","why":["","That is per hertz. The channel collects noise over all 20 MHz.","That leaves out the band, which is the larger term.","That is the thermal floor alone. The noise figure says how much the receiver adds to it."]},{"question":"A rectangular pulse of 16 samples is read by looking at one sample, then by averaging all of them. What does averaging gain?","options":["12.0 dB: the signal adds 16 times over, the noise only 4","0 dB: the pulse has the same height","24 dB: 16 times over in amplitude","3 dB: it can never gain more"],"answer":0,"explain":"The samples of the pulse add in step, and the independent noise adds in power: the SNR rises by the number of samples, 10 log₁₀ 16.","why":["","The height of the pulse is unchanged, but the noise on the average is much smaller.","That treats the noise as adding in step too. It adds as √16.","There is no such limit: the gain grows with the energy collected."]},{"question":"Why can nobody simply use the random code from Shannon's proof?","options":["Decoding by comparing with every codeword takes 2^(nR) comparisons, and n must be large","It does not actually reach the limit","Random codes have no check bits","It only works at low noise"],"answer":0,"explain":"A random code has no structure for a decoder to exploit. At n = 1000 and rate ½ that is 2⁵⁰⁰ words. The whole of modern coding is structure that keeps the performance and loses the search.","why":["","As n grows it does reach it. That is the proof.","Every bit of a codeword is redundant in a sense, and none is separately a check bit. That is no obstacle.","It works at any noise below the limit."]}],
  "modem": [{"question":"The NCO's tuning word is 542 and the clock 19 200 Hz. About what frequency comes out?","options":["1270.3 Hz: word · 19 200 / 2^13","542 Hz: the word is the frequency","635.2 Hz: half the word, to stay under Nyquist","35.4 Hz: the clock divided by the word"],"answer":0,"explain":"The accumulator wraps every 2^13 / word = 15.11 clocks, one sine period, so f = word · f_clk / 2^13.","why":["","The word is a fraction of a turn per clock, not hertz. It is hertz only after multiplying by f_clk / 2^13.","Nyquist limits the highest word to half the table; it does not halve the frequency.","A divider would make the period the word; here the word is the step, so a bigger word is a faster tone."]},{"question":"A 16-QAM modem is moved from a line of 25 dB SNR to one of 18 dB, same symbol rate. What happens at the receiver?","options":["The error rate rises from 3e-15 to 6e-4 a symbol: the points are as far apart in absolute terms, with more noise round each","Nothing: the decision boundaries scale with the noise","The carrier frequency drifts","The symbol rate falls automatically"],"answer":0,"explain":"The points stay where they are; the noise cloud round each grows. The chance that a cloud crosses a boundary follows the Gaussian tail, so a few dB changes it by orders of magnitude. A real modem answers by dropping to a smaller constellation.","why":["","The boundaries are halfway between points and do not know about the noise.","The carrier is a separate matter from the noise power.","Nothing in the receiver changes the rate by itself; the two modems negotiate it."]},{"question":"V.90 reaches 56 kb/s downstream. Why is that no counter-example to Shannon?","options":["The downstream path from the server is digital to the line card, so only the local loop adds noise: about 4 kHz at more than 42 dB SNR is enough, and Shannon is satisfied","The telephone line has more bandwidth than 3.1 kHz, so the limit does not apply","Compression: the data is 56 kb/s after the modem, fewer bits before","V.90 uses more bits per symbol than Nyquist allows"],"answer":0,"explain":"8000 symbols a second of 7 bits each is 56 000 b/s through about 4 kHz: 42.1 dB at the least. V.34, with the caller's analog line converted to PCM at the exchange, could not have that; V.90 removes the conversion from the downstream path.","why":["","The limit applies to whatever band is used. Used with 4 kHz it still needs the SNR above.","Compression raises the user's rate, not the line's bit rate, which is what V.90 quotes.","Nyquist bounds symbols a second (2B real values); it does not limit bits a symbol, which the SNR does."]}],
  "carriers": [{"question":"An 8-point FFT has 12 butterflies. How many of them need the general complex multiplier?","options":["None: seven have W = 1, three −j, and two are 45° turns made of constant multipliers","All twelve","Eight: one per output","Four: one per column, plus one"],"answer":0,"explain":"The general multiplier only appears from 16 points on. That is why the butterfly count overstates the arithmetic of small transforms.","why":["","That is what N / 2 · log₂ N suggests, but it counts wires as multiplications.","The count is by twiddle, and an output has nothing to do with it.","Only the last column has any non-trivial twiddle."]},{"question":"Why does a streaming FFT cost so much less than the unrolled network of the same size?","options":["Each butterfly gets a different clock, so one butterfly and one multiplier a stage serve them all, in exchange for N − 1 samples of memory","It computes fewer butterflies","It works in lower precision","It drops the bit reversal"],"answer":0,"explain":"Every butterfly of the network still happens, one at a time. The price is memory and latency, and a throughput of one sample a clock instead of N.","why":["","The arithmetic done per block is the same.","Both are built at the same word length here.","The tones still come out bit-reversed: the order is a property of the factorization."]},{"question":"Water-filling leaves a tone dry. What does that mean about it?","options":["Its floor Γ / g is above the water level: any power there would buy less than the same power spent on the better tones","It has failed and must be repaired","It is carrying 15 bits already","Its gain is exactly 1"],"answer":0,"explain":"At the optimum all tones in use have the same marginal rate, 1 / μ. A tone whose very first watt earns less than that gets none, and a stronger budget can raise the level over it later.","why":["","It may be a perfectly good tone that the budget does not stretch to.","A full tone has a low floor, not a high one.","The value of the gain only matters against the level."]}],
  "serial": [{"question":"A stream of 8b/10b codes is received with a run of seven equal bits in it. What happened?","options":["A bit was corrupted on the line, since no legal stream has a run longer than five","Two codes of the same disparity followed each other","The scrambler seed was wrong","The comma moved"],"answer":0,"explain":"The code book has runs of at most 5, across code boundaries too (checked over all 268² pairs at both disparities). Seven means the line is not carrying a legal stream.","why":["","Disparity bounds the count of ones, not runs, and the encoder alternates the forms to keep it within one.","There is no scrambler in 8b/10b; its bound is in the table.","A comma only marks a boundary; the stream stays legal wherever it is."]},{"question":"A sender's bit clock is 2 % fast. The receiver's loop tolerates 3.1 % on a stream with an edge every other bit. What happens?","options":["It follows, slipping its strobe by one sample every few words","It loses lock within a word","It follows only while the data are random","It needs a new comma every word"],"answer":0,"explain":"At 2 % the sender drifts 0.08 sample a bit, a sample every 12 bits, and the loop makes a slip every F = 4 votes, about every 8 bits on a stream with edges at half the bits.","why":["","Only past the limit: the votes cannot move the strobe as fast as the data drift.","Any pattern with edges works; fewer edges means a smaller range, not none.","The comma sets the word boundary once; the strobe is tracked separately."]},{"question":"Why does PAM4 sometimes carry a lossy channel at a higher bit rate than NRZ?","options":["Half the symbol rate saves more channel loss than the three-times smaller eye costs","Its levels are further apart","It needs no clock recovery","The line code is shorter"],"answer":0,"explain":"Four levels shrink each eye to a third (9.5 dB). Halving the symbol rate halves the Nyquist frequency, and a trace whose loss in dB grows with frequency saves more than that once the loss at Nyquist is past about 19 dB.","why":["","They are closer: spacing is a third of NRZ's swing at the same peak amplitude.","It needs the same recovery, at the symbol rate.","PAM4 changes the levels, not the code that guarantees transitions."]}],
  "glass": [{"question":"Why did long-haul systems move from 1310 nm to 1550 nm, when dispersion is near zero at 1310 nm?","options":["Loss sets the amplifier spacing, it is lower at 1550, and erbium amplifiers work there; dispersion can be compensated or undone","Lasers do not work at 1310 nm","Dispersion is lower at 1550 nm","Water absorbs less at 1310 nm"],"answer":0,"explain":"0.25 against 0.15 dB/km is 8 dB over an 80 km span, and the erbium amplifier's band is 1530 to 1565 nm. Dispersion became an engineering matter; loss stayed physics.","why":["","Lasers work well at 1310 nm; it is the first long-haul window.","It is about 17 ps/(nm·km) at 1550, which is far more than at 1310.","The water line is at 1383 nm, near 1310 but it is not why."]},{"question":"Doubling the bit rate of an uncompensated link with a clean laser: what happens to its dispersion-limited reach?","options":["It falls by four: pulses are half as long and spread twice as fast","It halves","It falls by sixteen","It is unchanged"],"answer":0,"explain":"The spectrum is twice as wide, so it spreads twice as fast, and a bit is half as long, so the same spread is twice as bad. Reach goes as 1 / B².","why":["","That is the case of a source wider than the modulation.","That is what happens going from 10 to 40 Gb/s: four times the rate.","The reach depends on the rate, through the pulse's bandwidth."]},{"question":"Far past the optimum launch power, each extra dB lowers SNR by about 2 dB. Why?","options":["Nonlinear noise rises with P³ while the signal rises with P, so the ratio falls as P²","The amplifiers saturate","The fibre starts to absorb more","The receiver overloads"],"answer":0,"explain":"The Kerr effect makes the index depend on intensity, and in a wide WDM system the result looks like noise that goes as the cube of the power. Signal over that noise goes as P⁻².","why":["","Amplifier saturation would hold the power down rather than make noise.","Loss in dB/km does not change with power at these levels.","A receiver has an attenuator in front of it. This is in the fibre."]}],
  "errors": [{"question":"A link flips each bit independently with probability 10<sup>−4</sup>. A 16-bit field is protected either by one parity bit or by a CRC-8. Which accepts more of the corrupted words?","options":["The parity bit: every pair of flips passes it","The CRC-8: eight check bits are more places to go wrong","They accept the same share: 2<sup>−r</sup> of the corrupted words","Neither accepts any: both detect every error"],"answer":0,"explain":"Parity accepts every even-weight error, and two flips are the commonest: about (n − 1)p/2 = 8.0e-4 of the corrupted words. The CRC-8 has no code word of weight 1, 2 or 3 on 16 data bits, so only four or more flips get through (80 of its 65 536 code words have weight 4): 3.3e-12 of the corrupted words, 240 036 044 times fewer.","why":["","More check bits do not add failure modes; what matters is which error patterns are themselves code words, and the CRC-8 has none of low weight.","The 2<sup>−r</sup> share is the limit for pure noise. At 10<sup>−4</sup> the few-flip errors dominate, and the two checks differ enormously on them.","Parity misses every even-weight error, and a CRC misses the patterns that are multiples of its generator."]},{"question":"A link with a round trip of 106 frame times runs go-back-N with a window of 8 frames and no loss. What utilization does it reach?","options":["8 / 106, about 8 %","100 %: no loss, no waiting","1 / 106, as for stop-and-wait","50 %"],"answer":0,"explain":"The sender can have 8 frames out and must then wait for the first acknowledgement, which comes a round trip (106 slots) after it was sent. It sends 8 frames in 106 slots.","why":["","Only when the window reaches 107 frames, the bandwidth-delay product plus one.","Stop-and-wait is a window of 1. A window of 8 sends eight frames per round trip.","There is no 50 % in this: the fraction is the window over the round trip."]},{"question":"Forward error correction is added to a link that sees one error in 10<sup>9</sup> bits, with a short round trip. What happens to goodput?","options":["It falls by the code's redundancy: there are almost no retransmissions to save","It rises, because every error is corrected","It is unchanged: the CRC still catches everything","It doubles, since frames are shorter"],"answer":0,"explain":"At a bit error rate of 10<sup>−9</sup> a 1500-byte frame is corrupted 0.0012 % of the time, so retransmission costs almost nothing, while SEC-DED(72, 64) sends 12.5 % more bits on every frame: goodput 88.7 % against 99.7 %.","why":["","It does correct every single error, but there are so few that the saving is smaller than the redundancy paid on every frame.","The CRC is still needed, but the frame is 12.5 % longer on the wire, so goodput changes.","The check bits make frames longer, not shorter."]}],
  "codes": [{"question":"What does the Reed-Solomon decoder's discrepancy unit compute in its two passes?","options":["Both times Σ λ_j S_(r − j): in the first pass the next syndrome against the register's prediction, in the second the coefficients of Ω","The syndromes, then the error values","The inverse of δ, then of γ","The locator's roots, then their count"],"answer":0,"explain":"One sum, two uses: that is why Ω costs no new multipliers. Only the window differs: the mask stops the sum wrapping round to the far end of the ring in the second pass.","why":["","The syndromes are built by Horner as the word arrives, and Forney finds the values.","The inversionless form never divides by δ or γ; the only inverse is in Forney.","Chien's search finds the roots and a counter counts them."]},{"question":"A link's concatenated decoder fails often. Doubling the interleaver depth cuts failures a lot, at no change in rate. What does this say?","options":["The inner decoder's errors arrive in bursts, and the words were limited by bursts, not by the average rate of errors","The outer code was too weak at any depth","The inner code's rate had changed","The channel's noise had fallen"],"answer":0,"explain":"Interleaving changes nothing but where wrong bytes land. If that helps, wrong bytes were clumped.","why":["","A code too weak at any depth would not have improved so much.","The interleaver has no effect on the rate.","It has no effect on the noise."]},{"question":"Density evolution says a (3, 6) code's threshold on the erasure channel is about 0.429. What does a threshold promise?","options":["Below it, a typical long enough code decodes nearly everything; above it, no length helps this code with this decoder","Every code with these degrees corrects exactly this share of erasures","A word of any length corrects up to it","It is the capacity of the channel"],"answer":0,"explain":"It is a property of the ensemble and the decoder, in the limit of long blocks. Capacity at rate ½ is 0.5, higher than this.","why":["","A particular unlucky code may do worse: the claim is about typical ones.","Short words stall below it.","Capacity at rate ½ on this channel is 0.5."]}],
  "pcie": [{"question":"A TLP arrives with a good LCRC but a sequence number one below what the receiver expects. What does the receiver do?","options":["Drops it and sends an Ack: the sender evidently missed the earlier Ack","Delivers it again, since its LCRC is good","Sends a Nak, since the number is wrong","Retrains the link"],"answer":0,"explain":"An old sequence number with a good LCRC means the sender is replaying something already delivered, which only happens if the Ack was lost. Delivering it would duplicate a memory write. Acknowledging it stops the replay.","why":["","That duplicates a write: the replay exists for the sender, and the receiver filters it.","A Nak asks for a replay of what it already has. A Nak is for a number ahead of the expected one, or a bad LCRC.","Nothing is wrong with the link."]},{"question":"Why do credit counters compare with a modular subtraction rather than LIMIT ≥ CONSUMED + want?","options":["Both counters are free-running and wrap, so only their difference means anything","The subtraction takes fewer gates than a comparator","It lets the sender borrow credits it has not been given","The receiver sends credits as differences"],"answer":0,"explain":"An 8-bit header counter wraps after 256 TLPs. Right after CONSUMED wraps and before LIMIT does, or the other way round, a plain comparison gives the wrong answer. The difference modulo the field is right as long as the two are never more than half the range apart, which the receiver's buffer size guarantees.","why":["","A comparator and a subtractor cost about the same. The reason is the wrap.","The test refuses exactly what was not given.","UpdateFC carries the absolute running total, not a difference, so that a lost update is repaired by the next one."]},{"question":"A SET_ADDRESS request is acknowledged in its setup stage. When may the device start answering to the new address?","options":["After the status stage completes, which is still addressed to the old one","At once, as soon as the setup packet is acknowledged","After the next bus reset","When the host sends the first token with the new address, whatever the state of the transfer"],"answer":0,"explain":"The whole control transfer happens at the old address, status stage included. A device that moves early never hears the IN token of its own status stage, and the host gives up on it.","why":["","That is the classic bug: the status stage is still addressed to 0.","A bus reset takes it back to address 0.","The device has to have moved by then, and it moves at the end of the status stage."]}],
  "ethernet": [{"question":"A frame carries 20 bytes of payload. What does the transmitter put on the wire after the 14-byte header and the payload?","options":["26 zero bytes of pad, then 4 bytes of FCS","Nothing: the receiver pads short frames","The FCS only, 4 bytes","26 bytes of pad, and the FCS in the preamble"],"answer":0,"explain":"The frame must be at least 64 bytes with its FCS, so 60 before it: 14 + 20 + 26 = 60. The pad is not covered by any length field in Ethernet II, so the layer above has to know the real length (IP's header carries it).","why":["","The receiver cannot add bytes that the FCS covers: the FCS is computed by the sender over the padded frame.","That frame would be 38 bytes, a runt that receivers drop.","The preamble comes before the frame and is not covered by the FCS; the FCS follows the pad."]},{"question":"Two stations 20 µs of cable apart both start a 64-byte frame at 10 Mb/s, B 10 µs after A. Who detects the collision first?","options":["B, when A's signal reaches it 20 µs after A started, B being already sending","A, 10 µs after it started","Neither: a frame shorter than the round trip hides it","Both at the same moment"],"answer":0,"explain":"A's first bit reaches B at 20 µs; B started at 10 µs, so B has been sending for 10 µs and hears another carrier: it detects first. B's first bit reaches A at 30 µs, and A, still sending (a minimum frame plus preamble lasts 57.6 µs), detects then.","why":["","A cannot hear B before B's signal has crossed the cable: 10 + 20 = 30 µs after A started.","A's frame lasts 57.6 µs and B's signal reaches A at 30 µs, inside the frame, so A does see it.","Each hears the other after the cable delay from that other's start, and the starts differ by 10 µs."]},{"question":"A station has collided three times with the same frame. How many slot times can its next backoff be?","options":["0 to 7","0 to 3","0 to 15","Exactly 8"],"answer":0,"explain":"After the n-th collision r is drawn from 0 to 2^min(n, 10) − 1; after the third that is 0 to 7, so on average a wait of 3.5 slots. The range doubles with each collision, which is how a crowd of contenders is thinned out without anyone counting them.","why":["","That is the range after the second collision.","That is the range after the fourth collision.","The draw is random; two stations with the same fixed count would collide again forever."]}],
  "switch": [{"question":"A frame arrives at a switch with an empty table. Its destination address is a unicast address. What does the switch do with it, and what does it learn?","options":["It floods the frame to every port but the arrival port, and learns the source address on the arrival port","It drops the frame, because it cannot place the destination","It sends the frame back out of the arrival port to find the destination","It floods the frame and learns the destination address on every port"],"answer":0,"explain":"A miss is flooded to every port except the source, so the destination host (wherever it is) gets the frame. The source address on the frame tells the switch where the sender is, which is the only thing a frame teaches it.","why":["","Dropping would leave a new host unreachable until it spoke first; a switch floods what it cannot place.","A frame is never returned to its source port: the sender is on that wire and would see its own frame.","The destination address says nothing about where that host is. Only the source address of a frame arriving on a port reveals what sits behind it."]},{"question":"Four inputs each keep one FIFO. The oldest frame of input 0 waits for a busy output while input 0 has a younger frame for an idle output. Which statement is true?","options":["The younger frame waits too: only the head of each FIFO competes, which is head-of-line blocking","The younger frame is sent at once because the crossbar is non-blocking","The switch reorders the two frames, since frames may be reordered freely","The younger frame is dropped to make room"],"answer":0,"explain":"With a single queue per input only the head can be offered to an output. The crossbar could carry the younger frame, but the queue does not show it. A queue per output removes the effect, given cells enough to look past the blocked frame.","why":["","The crossbar is non-blocking, which is exactly why the loss is in the queue and not in the fabric.","A switch keeps the frames of one flow in order, and these may well belong to one flow.","Nothing is dropped while a cell is free; the buffer holds both frames."]},{"question":"A 1518-byte frame crosses one hop at 100 Mb/s. About how much latency does cut-through save against store-and-forward?","options":["About 120 µs: the frame time of 1526 bytes less the header time","Nothing: the last byte leaves at the same time either way","About 1 µs, the interframe gap","About 12 ns, the lookup time"],"answer":0,"explain":"Store-and-forward waits for the whole frame: (1518 + 8) bytes at 100 Mb/s is 122 µs. Cut-through waits for the preamble and the header, about 2 µs. With cut-through the first byte leaves some 120 µs sooner, and so does the last when the output is free.","why":["","The whole frame starts sooner with cut-through, so its last byte leaves sooner too, by about the same 120 µs.","The interframe gap is 12 byte times (0.96 µs at 100 Mb/s) and is spent on the wire in both designs.","A lookup takes a few clock cycles, far less than a frame time, and it is not what separates the two designs."]}],
  "network": [{"question":"The NIC has written 40 bytes of a received frame into its buffer when the frame turns out to have a wrong FCS. What does the driver see?","options":["Nothing: the descriptor is still the NIC's, and the next frame overwrites the buffer","The descriptor with OWN clear and a length of 40, which it must check against the status register","The descriptor with OWN clear and an error flag in the length field","An interrupt, so that it can clear the buffer"],"answer":0,"explain":"The NIC writes word 1 (the length, OWN clear) only at the commit, after the verdict on the FCS. Until then the descriptor says the NIC holds it, and the driver, which looks only at OWN, cannot tell that the buffer has been written at all.","why":["","Word 1 is written last. With a bad FCS it is never written, so nothing carries a length of 40.","The only flags a receive descriptor carries are OWN and the length; a bad frame is not handed back at all.","The interrupt follows a commit. A frame that is forgotten raises STATUS.BAD, which the driver may read, but no interrupt."]},{"question":"A block of bytes includes its own 16-bit checksum field. The receiver adds all the words, folds the carries back in and gets 0xFFFF. What does that say?","options":["The block is consistent with its checksum","The block is certainly intact","The checksum field was zero when the sender computed it","The block has an even number of words"],"answer":0,"explain":"The checksum is the complement of the sum of the rest, so the whole block sums to all ones. A single flipped bit changes the sum and is caught; two flips that cancel, or words that swap, are not.","why":["","The sum is a 16-bit fingerprint. Some changes leave it unchanged, so passing is evidence and not proof.","The sender does compute with the field zeroed, but the receiver's 0xFFFF comes from the field being complete, not from it being zero.","An odd last byte is padded with a zero, so the length does not matter."]},{"question":"A 74-byte ping frame holds this link for 3136 clocks, gap included, and the CPU needs 1882 clocks to receive and answer it. What follows?","options":["The CPU keeps up with a stream of them, with 40 % of each frame time to spare","The CPU falls further behind with every frame","The CPU is idle for most of each frame time, waiting for the cable","The two cannot be compared: one is time on a cable and the other time in a CPU"],"answer":0,"explain":"1882 against 3136 is 60 %. A frame arrives every 3136 clocks at the most, and the software finishes with the rest of that period left over; at ten times the link speed the period would be 314 clocks and the same work would no longer fit.","why":["","At full line rate a frame arrives every 3136 clocks and the stack needs 1882: it finishes first, every time.","The stack is busy for 60 % of each frame time, and 40 % is left over.","Both are counted in the same clock: the CPU, the MAC and the bus all run on it."]}],
  "router": [{"question":"The table holds 10.0.0.0/8 via hop 1, 10.1.0.0/16 via hop 2 and 10.1.2.0/24 via hop 3. Where does 10.1.3.4 go?","options":["Hop 2: the /8 and the /16 match, and the /16 is longer","Hop 3: the /24 is the longest in the table","Hop 1: the first route that matches wins","Nowhere: no entry equals the address"],"answer":0,"explain":"10.1.3.4 is not in 10.1.2.0/24, since the third byte differs. Of the two that match, the longest prefix wins.","why":["","The /24 covers 10.1.2.x only.","Order means nothing: length decides, which is why a /32 can sit next to a default route.","A route is a prefix, not an address: that is what makes a table far smaller than the number of hosts."]},{"question":"Why can a router update the checksum without reading the rest of the header again?","options":["The sum is linear: one word changed by a known amount, so the old sum changes by the same amount","The TTL is not covered by the checksum","The checksum is recomputed by the next router anyway","It only checks the addresses"],"answer":0,"explain":"A one's-complement sum of words moves by exactly what one word moves by. Lowering the TTL lowers the word {TTL, protocol} by 0x0100, so the update is one constant addition, whatever the header holds.","why":["","It covers the whole header, TTL included, which is why it changes at every hop.","Every router verifies it, so a wrong one would be dropped at the next hop.","It covers all twenty bytes."]},{"question":"On A - B - C the link B - C fails. Without poison reverse, why does the cost to C climb one or two a round?","options":["B hears A's old route to C, which ran through B, and believes it; then A believes B","Each router lowers its TTL","A floods the failure one hop a round","The link's cost rises while it is down"],"answer":0,"explain":"A's table only says \"2 to C\". It does not say the path runs through B, so B takes it, and each then raises its cost on the other's word until both reach infinity, here 16.","why":["","TTL is on packets; this is about tables.","Nothing is flooded in distance vector, and A never learns of the failure as such.","The cost of a link down is simply gone: B stops using it at once."]}],
  "tcp": [{"question":"A sends a SYN with sequence number 1000. B answers with SYN, sequence number 5000. What does its acknowledgment field say?","options":["1001: the SYN holds a sequence number of its own, and 1001 is what B expects next","1000: the last byte received","5001: B's own next number","0: no data has arrived yet"],"answer":0,"explain":"An ACK names the next byte expected, not the last one seen, and SYN and FIN each use up one sequence number so that they can be acknowledged and retransmitted like data.","why":["","That would say the SYN itself has not arrived: an ACK names what comes next.","5001 is what A will acknowledge, in the third segment.","A SYN holds a sequence number precisely so that it can be acknowledged."]},{"question":"cwnd is 16 segments and the receiver announces a window of 8 segments. How much may be unacknowledged?","options":["8 segments: the smaller of the two","16 segments: cwnd is the sender's own","24 segments: they add","4 segments: half the smaller"],"answer":0,"explain":"The sender obeys both limits: min(cwnd, rwnd). In the wire-speed run of this chapter cwnd climbs to 16 segments, while the receive window keeps what is in flight to 8.","why":["","Sending past the receive window fills a buffer that is not there.","They are two limits on one quantity, not two allowances.","Halving is what a loss does to cwnd, and only then."]},{"question":"The router's queue holds 2 frames and the window is rarely above 4 segments. A frame is dropped. Why does this usually end in a timeout?","options":["Too few segments follow the lost one to produce three duplicate ACKs","Duplicate ACKs are not sent when the queue is short","A short queue makes the round trip too short to measure","The router tells the sender to wait"],"answer":0,"explain":"Each duplicate ACK needs a later segment to arrive. With two or three in flight there are not three later ones, so only the timer can notice, and it waits a whole RTO and then falls to one segment.","why":["","The receiver sends one for every out-of-order arrival, whatever the queue.","A shorter round trip is measured just as well, and is what a short queue gives.","Routers here say nothing; a drop is the only signal."]}],
  "queues": [{"question":"A link is 80 % loaded with random packet sizes. What is the mean wait, and what would it take to halve it?","options":["4 packet times; reduce the load to two thirds (ρ / (1 − ρ) = 2)","4 packet times; halve the load","0.8 packet times; it is already small","20 packet times; only a faster link helps"],"answer":0,"explain":"ρ / (1 − ρ) at 0.8 is 4, and solving for 2 gives ρ = 2 / 3. Halving the traffic overshoots a long way, to a wait of 2 / 3 of a packet.","why":["","Halving the load gives ρ = 0.4 and a wait of 0.67, not 2.","That is ρ, not ρ / (1 − ρ).","1 / (1 − ρ) is 5, not 20, and lower load helps as well."]},{"question":"A flow's window is W at the top of its sawtooth, and its RTT is 100 ms. With no queue at all and W the pipe, what share of the link does Reno average?","options":["¾: the window runs evenly from half of the pipe to all of it","All of it: the window never falls under the pipe","½: it spends all its time halved","It depends on the RTT"],"answer":0,"explain":"The average of W / 2 to W is ¾ W. With a queue, the window can stay above the pipe for some of the cycle, and at B = P the link never idles.","why":["","It falls under the pipe at once, with no queue to drain.","It rises steadily from there, so the mean is above half.","The RTT sets how long a cycle is, and not the shape of it."]},{"question":"Why does a queue per flow end the argument between BBR and CUBIC?","options":["Each sender has its own queue and an equal turn, so its rule only affects itself","It makes them both BBR","It makes the buffer larger","It stops all losses"],"answer":0,"explain":"The share is decided by the scheduler. A sender that ignores drops only overflows its own queue.","why":["","The senders do not change.","It does not need to be larger: it is used differently.","A sender that overruns its queue still loses packets, its own."]}],
  "secret": [{"question":"Why can't an Enigma encipher a letter to itself?","options":["The reflector sends the current back by a different path, and the pressed key has cut off its own lamp","The rotors skip the input letter on purpose","The plugboard swaps every letter","The operators were told not to send such letters"],"answer":0,"explain":"A reflector pairs every contact with a different one, so the current returns on another wire. And electrically, the pressed key's changeover switch has disconnected that letter's lamp.","why":["","Nothing selects against a letter: the wiring has no fixed path back to the same contact.","Plugged or not, the reflector's pairing is what rules it out; six letters are usually unplugged.","It is the machine that cannot do it, whatever the operator wants."]},{"question":"The plugboard gives 1.51 × 10<sup>14</sup> settings of ten cables. Why did the Bombe not need to try them?","options":["A guess at one plug follows through the known scrambler, so a contradiction rejects the wheel position for every plugging at once","It tried them all, very fast","Bletchley Park had the daily plug settings from captured sheets","The plugboard made no difference to the cipher"],"answer":0,"explain":"The reasoning needs only that a plug is a swap. It discards a wheel position without enumerating pluggings: the huge factor in the key space never enters the search.","why":["","At a million plug settings a second, that alone takes about five years for each wheel position, and there are 17 576 positions per wheel order. No machine tried them.","Captured material helped at times, but the Bombe's method needed no plug settings.","It multiplied the key space enormously. The point is that the method goes round it, not that it is absent."]},{"question":"A picture is enciphered with AES in ECB mode, and its outline is still visible. Why?","options":["Equal 16-byte blocks of input give equal blocks of output","AES is too weak to hide images","The key was too short","ECB leaves the first round out"],"answer":0,"explain":"Each block is enciphered alone with the same key, so a flat area of the picture turns into one repeated block. The cipher is doing its job on each block; the mode gives the pattern away.","why":["","AES is fine: the same cipher in CTR mode hides the picture completely.","A longer key changes which block each block turns into, not that equal blocks stay equal.","ECB runs all the rounds. The problem is what happens between blocks: nothing."]},{"question":"Eve records a whole X25519 exchange and has unlimited storage. What stops Eve computing the shared secret?","options":["A private key is needed, and getting one from a public key is a discrete logarithm, out of reach of ordinary computers at this size","The public keys are encrypted","The secret is sent under AES","The exchange is too fast to record"],"answer":0,"explain":"Eve sees both public values. No known way of combining them into the secret is easier than solving the discrete logarithm on the curve. A large quantum computer would change that: Shor's algorithm solves discrete logarithms.","why":["","They are sent in the clear, in the ClientHello and ServerHello: anyone can read them.","The shared secret is never sent at all, under anything. Both sides compute it.","Recording is easy. The protection is in the mathematics, not in timing."]},{"question":"A TLS 1.3 handshake completes with no certificate check. What has been achieved?","options":["An encrypted channel to whoever answered, who may be an attacker","Nothing: without a certificate the keys are not secret","Full security: encryption is what matters","The handshake cannot complete without one"],"answer":0,"explain":"Key exchange gives a secret shared with the other end, whoever that is. A man in the middle simply runs one exchange with each side. Authentication is a separate job, and the signature over the transcript does it.","why":["","The keys are secret from a passive listener; the trouble is the active one.","An attacker in the middle reads and changes everything, under keys shared with you.","The chapter’s client completes with no pin, and says so: the mathematics does not require one."]},{"question":"Which of these machines stored its program in the memory it worked on?","options":["The Manchester Baby, 1948","The Bombe","Colossus","The M4"],"answer":0,"explain":"Colossus was electronic and set up by switches and plugs, but its program was not in memory. The Baby first ran a program from read-write electronic memory on 21 June 1948.","why":["","A Bombe was built for one job and wired by a menu.","Colossus was programmable by switches and plug panels and had no stored program.","An Enigma has no program at all: the wiring is the function."]}],
  "path": [{"question":"Why does the laptop's traffic to Quillon cross two backbones, when Ridgeway has a direct peering link to Orchard, a customer of Quillon's provider?","options":["Orchard learned that route from its provider, and sends a provider's routes only to its customers","The backbones are physically shorter","BGP measures delay, and the peering link is slower","Ridgeway has not heard of Orchard"],"answer":0,"explain":"Carrying Ridgeway's traffic up to Tarn would make Orchard pay its provider for traffic that earns it nothing. So Orchard never offers the route, and Ridgeway never sees it.","why":["","They are 1590 km longer here: distance is exactly what this choice does not use.","BGP carries no delay at all, only the path and policy.","It has: its routes to Brackwater go over that link."]},{"question":"A traceroute shows hop 7 at 12 ms and hop 8 at 9 ms. What does that show?","options":["Nothing wrong: each line is a separate packet with its own queues, and each reply has its own way back","The packet travelled back in time on a cheaper link","Hop 7 is overloaded and hop 8 is not on the path","The TTL was counted wrongly"],"answer":0,"explain":"The probes are different packets at different times. A router may also answer slowly because a reply goes through its slow path, without slowing the packets it forwards.","why":["","The later line is a different packet, so the two times are not two points on one journey.","Both are on the path: hop 8 answered a probe that crossed hop 7.","Each probe's TTL is one more than the last, and the answers name who killed each."]},{"question":"Which change shortens this path's round trip the most, for a small packet?","options":["A copy of the site nearer the laptop","Backbone links ten times faster","Routers with a faster fast path","A larger TCP window"],"answer":0,"explain":"Light is 47.5 of the 47.7 ms one way. Only moving the far end changes that.","why":["","A small frame already takes well under a microsecond on a 100 Gb/s link.","Each engine takes about 549 ns; even all of them together are a small part.","A window affects how much data flows per round trip, not how long the round trip is."]},{"question":"A page comes over HTTP/2 and one TCP segment is lost. What waits for the retransmission?","options":["Everything later on that connection, whichever object it belongs to","Only the object that segment belonged to","Nothing: HTTP/2 retransmits frames itself","The whole page is requested again"],"answer":0,"explain":"TCP delivers one ordered stream of bytes and knows nothing of HTTP/2's streams, so bytes past the gap stay in its buffer. RFC 9113 says this blocking is not addressed. QUIC moves streams into the transport, which is what limits a loss to one.","why":["","That is QUIC. HTTP/2's streams exist only above TCP.","Frames have no retransmission of their own: HTTP/2 relies on TCP for that.","Only the lost segment is sent again."]}],
  "radio": [{"question":"A link in free space works out to 60 m. Somewhere you lose 6 dB more. How far does it work now?","options":["30 m: each doubling of distance costs 6 dB","15 m","60 m: 6 dB is small","20 m"],"answer":0,"explain":"20 log d: a factor of 2 in distance is 6 dB. A 6 dB shortfall halves the range, in free space. Through walls and with an exponent of 3 to 4, 6 dB buys less distance than that.","why":["","That is the factor for 12 dB.","Six dB is a factor of four in power.","There is no such rule: the exponent is 2 in free space."]},{"question":"Why doesn't 5 GHz \"reach\" as far as 2.4 GHz with the same antennas, and why doesn't the air explain it?","options":["A same-gain antenna at the higher frequency is smaller and collects less; and walls do absorb more","Air absorbs most of it","Radio waves slow down at higher frequencies","A higher frequency has more noise in it"],"answer":0,"explain":"Free space does not dissipate anything. λ² / 4π is the area an isotropic antenna collects, and it falls with frequency. Absorption in air only matters in narrow bands, like the oxygen line at 60 GHz.","why":["","Air absorption is negligible below tens of GHz.","In free space all frequencies travel at c.","Thermal noise per Hz is the same at both."]},{"question":"A channel has a 300 ns delay spread. A 20 MHz single-carrier symbol is 50 ns. What does that mean?","options":["Each symbol's echo overlaps several later ones: it needs equalizing, or many slow carriers","Nothing: a delay does not change the bits","The channel is too slow to use","The Doppler shift will correct it"],"answer":0,"explain":"Coherence bandwidth is about 0.7 MHz, far below 20 MHz, so the channel is frequency-selective. A long symbol, by many narrow carriers, makes the same echo a small fraction of it. That is OFDM, from chapter 50.","why":["","Six symbols of overlap is severe inter-symbol interference.","It can be used, by equalizing or by OFDM.","Doppler is a matter of speed, not of delay spread."]}],
  "wifi": [{"question":"A station has sent a frame and hears no ACK. What does it know?","options":["Only that no ACK came: the frame was lost, or the ACK was","That the frame collided with another","That the receiver is out of range","That the frame arrived, since a radio delivers what it sends"],"answer":0,"explain":"A radio cannot detect the collision. The missing ACK has many causes, including noise and a weak signal, and DCF treats them all alike as collisions, doubling the window. That is why low SNR can look like congestion.","why":["","Could be: or noise, or the ACK itself was lost.","Could be, but a missing ACK does not say so.","Nothing confirms delivery but the ACK."]},{"question":"Why is SIFS shorter than DIFS?","options":["So that a response to a frame always goes ahead of any new frame: the exchange stays whole","To make frames faster","Because ACKs are short","To save power"],"answer":0,"explain":"A station with a new frame must see the medium idle for a whole DIFS. An ACK begins after SIFS, so nobody following the rules can get in between.","why":["","It does not change a frame's speed.","An ACK's length has nothing to do with the gap before it.","Waiting is receiving, and uses about the same power."]},{"question":"Two laptops are each in range of an access point but not of each other. What does RTS / CTS change?","options":["The access point's CTS is heard by both, so the other holds off for the announced time; a collision costs only a short RTS","They can now hear each other","The access point schedules them in turn","The access point transmits both frames"],"answer":0,"explain":"They still can't hear each other. A lost RTS costs tens of microseconds, not a whole frame; and once a CTS goes out, it sets the NAV of everyone in range of the receiver.","why":["","Their radios are as far apart as before.","Nothing here is scheduled: the RTS still contends.","Each station sends its own data."]}],
  "cellular": [{"question":"Why did LTE go to reuse 1, when K = 7 gives 15 dB or more of SIR?","options":["Rate grows only with log(SIR) but linearly with bandwidth, so sharing the whole band and coding for low SIR carries more","Reuse 1 has a better SIR","Other frequencies were not available","K = 7 cells are physically harder to plan"],"answer":0,"explain":"In this model the median SIR at K = 1 is only 4 dB and at K = 7 it is 21 dB; but K = 7 gives each cell a seventh of the band. Log wins: 2.67 against 1.09 b/s/Hz. Edge users are then helped by scheduling and interference coordination.","why":["","Its SIR is far worse. It wins anyway.","Scarcity is the premise of this trade, not an alternative to it.","Planning is a reason, a secondary one."]},{"question":"Eight users all at the same mean SNR. Why does max-rate scheduling beat round robin, when all else is equal?","options":["It serves each user only at its fading peaks, so the average served SNR is several times the mean","It has less overhead","It uses more power","It serves more users per slot"],"answer":0,"explain":"The best of 8 Rayleigh users has H_8 = 2.72 times the mean SNR, which in this model takes the cell from 2.91 to 4.68 b/s/Hz. With users at the same mean, it costs no fairness either.","why":["","Both have the same overhead here.","Same power in both.","One user per slot in both."]},{"question":"Handover drops calls at the cell edge at high speed. Which change helps most?","options":["Lower the time to trigger and hysteresis, accepting more back-and-forth","Raise the hysteresis","Raise the time to trigger","Remove shadowing"],"answer":0,"explain":"A fast phone covers more metres during the time to trigger, and the serving signal may fall below usable before it fires. Handing over earlier trades that for ping-pongs when moving slowly, and real networks scale these by the phone's measured speed.","why":["","That delays handover further.","That delays handover further.","A network does not get to choose the buildings."]}],
  "datacentre": [{"question":"With 32 flows on 32 equal paths under ECMP, about what share of the fabric is used?","options":["About 64 %: a path is idle with chance (1 − 1 / 32)³²","100 %: there is one path for each flow","50 %","3 %"],"answer":0,"explain":"A hash does not look at load, so some paths get two or more flows while others get none: 1 − 1 / e in the limit.","why":["","It would need a scheduler to place each flow on its own path.","That is lower than balls in bins gives.","That would be one path in thirty-two."]},{"question":"Why does a stock 200 ms timer hurt a data centre so much more than it hurts a web user?","options":["The round trip is 100 µs, so 200 ms is thousands of round trips of idle link, and the whole read waits for it","Data centre links are slower","The web has no timers","Web pages cannot tolerate any delay"],"answer":0,"explain":"On the internet a 200 ms timer is a few round trips. Here it is thousands, spent idle with data waiting.","why":["","They are far faster: that is what makes the ratio so large.","It has the same timers, on far longer round trips.","On the web 200 ms is a few round trips, which a user barely notices."]},{"question":"What does making Ethernet lossless cost?","options":["Headroom per port and class, innocent flows held up by pauses, and the possibility of deadlock","Nothing: it is strictly better","Half the bandwidth","All other traffic classes must stop as well"],"answer":0,"explain":"A drop only hurts the flow it hits. A pause hurts whoever is queued behind it, and if pauses form a loop they never end.","why":["","That is the view this chapter sets out to correct.","It costs no bandwidth when there is no congestion.","Classes are paused one by one: that is the P in PFC."]}],
  "bench": [{"question":"A transfer is slow. The capture shows no retransmissions, and the round trip has grown from 2 ms to 400 ms during the transfer. What do you look at next?","options":["The buffers on the path: the data is waiting in a queue, not being lost","The cable: bits are being corrupted","The receiving program: it may not be reading","The server's disk"],"answer":0,"explain":"A round trip that grows with the bytes in flight, with nothing lost, is a queue filling. Nothing else on the list changes the round trip.","why":["","Corrupted bits would be retransmissions, and there are none.","A slow reader closes the window and leaves the round trip alone.","A slow disk at the far end shows as a closing window, which would leave the round trip flat as well."]},{"question":"A link's eye looks like clean thin traces that never reach the rails between bits. Which change is most likely to help?","options":["Equalization or more band: the bits are shaped by the ones before them","A stronger transmitter: the noise is winning","A better clock","A larger buffer"],"answer":0,"explain":"Thin traces mean little noise. What closes this eye is intersymbol interference, and that is answered by flattening the channel.","why":["","Thin traces show the noise is small. More power scales the interference with the signal.","Clock trouble smears the eye sideways. These traces are aligned.","A buffer works on packets. This fault is below the bit."]},{"question":"Why does the method insist on changing one thing at a time?","options":["Two changes at once leave you unable to say which one mattered, and a fault that went away that way can come back","Equipment can only be reconfigured once at a time","Changing two things always makes the fault worse","Faults only ever have one cause"],"answer":0,"explain":"Each change is an experiment. Keeping the experiment clean is what lets you trust the conclusion and the fix.","why":["","Equipment is not the limit: the limit is what you can conclude.","It may well fix it. You just cannot say why.","Faults can have several causes, which is one more reason to separate them."]}],
  "fixed": [{"question":"Two Q1.15 words are multiplied in a 32-bit result. Which 16 bits are the Q1.15 answer?","options":["Bits 30 down to 15","Bits 31 down to 16","Bits 15 down to 0","Any 16 bits: only the scale changes"],"answer":0,"explain":"The product is Q2.30, so its point sits below bit 30 and it has two sign bits. Bit 31 only repeats bit 30, except for −1 × −1.","why":["","That keeps the spare sign bit and halves every answer.","Those are the bits lost to rounding, and they say almost nothing about the size.","The point has a definite place, and only one choice keeps Q1.15."]},{"question":"An FIR filter wraps part way through its sum of products, but its final answer is known to fit. What is wrong with the output?","options":["Nothing: arithmetic modulo 2^w gets the same low bits in any order","It is off by the amount that wrapped","It is noisy until the next sample","Its sign is wrong"],"answer":0,"explain":"Every step is correct modulo 2^w. A value that fits in w bits is fixed by its residue, so the excursion leaves no trace.","why":["","A wrap removes exactly 2^w, and a later wrap, or the true sum fitting, gives it back.","No memory of the excursion remains in the word.","If the final value fits, the top bit is its true sign."]},{"question":"A chain cuts a signal by 8 and later raises it by 8. The signal only ever reaches a tenth of full scale. What is the better order?","options":["Up first, then down: nothing is lost, and the peak stays in range","Down first, to leave headroom","Either: the overall gain is 1","Neither: it needs a floating-point word"],"answer":0,"explain":"A tenth of full scale times 8 still fits, so going up first drops nothing. Going down first throws three bits away and the later gain cannot bring them back.","why":["","There is plenty of headroom already, and those three bits are about 18 dB.","The overall gain is the same, and the rounding noise is not.","Fixed point holds it with room to spare."]}],
  "zplane": [{"question":"A filter has one pole pair at radius 0.9, at an angle of a tenth of a cycle a sample. Roughly what does its output do after an impulse?","options":["Rings at a tenth of the sample rate, and falls by 0.9 each sample","Holds at 0.9 for ever","Stops after two samples, since it has two poles","Grows, since a resonance adds energy"],"answer":0,"explain":"The angle gives the ringing frequency and the radius the decay: the envelope is 0.9ⁿ.","why":["","That needs a pole at z = 1, on the circle.","Feedback keeps feeding the past in. Only FIR filters stop.","A pole inside the circle dies away, however sharply it peaks."]},{"question":"You want to remove a 50 Hz hum at 1 kHz sampling and leave the rest alone. Which placement does that?","options":["Zeros on the circle at 0.05 cycles a sample, and poles just inside at the same angle","Poles on the circle at 0.05, zeros at the origin","Zeros at z = 1","Poles and zeros both at the origin"],"answer":0,"explain":"The zero makes a null. Near it, the pole's distance nearly equals the zero's, so the ratio returns to about 1 quickly and the notch is narrow.","why":["","That builds an oscillator at 50 Hz.","That removes DC, not 50 Hz.","Those cancel, leaving no filter at all."]},{"question":"Why can an FIR filter be linear phase when a causal IIR filter cannot?","options":["Linear phase needs each zero paired with its mirror across the circle, and a pole's mirror would be outside, unstable","FIR filters have more multipliers","IIR filters only work on audio","Feedback removes the phase altogether"],"answer":0,"explain":"Symmetric taps come from mirrored roots. A zero can sit outside the circle freely; a pole cannot.","why":["","Cost and phase are separate questions.","IIR filters work on anything, and the limit is mathematical.","A feedback filter has phase like any other, and it is usually far from linear."]}],
  "spectrum": [{"question":"You zero pad a 64-sample block to 4 096 points before the FFT. What did that do?","options":["Evaluated the same continuous spectrum at more points: smoother curve, same main lobe","Made the main lobe 64 times narrower","Reduced the sidelobes by 36 dB","Added 4 032 samples of information"],"answer":0,"explain":"The zeros add no information. The transform of the block is one fixed curve, and padding only reads it at finer steps.","why":["","The lobe's width in cycles a sample is set by the number of real samples, 1 / 64.","Sidelobes belong to the window, and padding does not change the window.","The zeros are not measurements."]},{"question":"A tone 40 dB below another sits 10 bins from it. Which window shows it?","options":["Hann: its skirt there is under −60 dB","Rectangular: it has the narrowest main lobe","Neither: 40 dB is too weak for any window","Both, equally: the distance is outside either main lobe"],"answer":0,"explain":"At 10 bins the rectangle's skirt is −29.2 dB, above the weak tone, which hides under it. Hann's is −68.5 dB.","why":["","The narrow lobe helps resolve equal tones, not find a weak one: that is set by the skirt's height.","It is a matter of the skirt's level, and some windows reach −90 dB.","The lobes do not matter at 10 bins. The sidelobes do, and they differ by tens of dB."]},{"question":"A decoder needs 8 frequencies out of a 256-sample block. Goertzel or an FFT?","options":["Goertzel: 8 bins is under the break-even of 16","FFT: it computes every bin in N log N","FFT: Goertzel only works at bin centres","Goertzel: it needs no multiplications"],"answer":0,"explain":"One bin costs N real multiplications; the FFT's 4096 (counted at 4 per butterfly) buys all of them. Break-even is 16 bins.","why":["","Computing 129 bins to keep 8 pays for 121 you throw away.","It works at any frequency: c = 2 cos(2πf) takes any f. Off a bin centre it leaks like the FFT does.","It needs one a sample."]}],
  "firdesign": [{"question":"A symmetric FIR of 64 taps runs at 8 kHz. How long is its delay at 100 Hz, and at 3 kHz?","options":["3.9 ms at both","8.0 ms at both","3.9 ms at 100 Hz and less at 3 kHz","It depends on the passband ripple"],"answer":0,"explain":"Linear phase means one delay for all frequencies: (64 − 1) / 2 = 31.5 samples, and at 8 kHz that is 31.5 / 8000 = 3.9 ms.","why":["","That is the whole length, 64 samples; the delay is half of it.","Not for a symmetric filter; one delay for every frequency is what linear phase means.","Ripple is the gain's business; the delay comes from the length alone."]},{"question":"Why does a Kaiser-window design need more taps than Parks–McClellan for a mask with 0.1 dB of passband ripple and 60 dB of stopband?","options":["The window gives both bands one ripple, so it makes the passband far better than asked","Windows cannot make a sharp transition at all","Parks–McClellan uses complex taps","Kaiser windows are not symmetric"],"answer":0,"explain":"The mask lets the passband vary by 0.0058 and the stopband by 0.001. A window design ends up near 0.001 in both. Parks–McClellan weights the two bands as the mask does, and spends the slack on a narrower transition.","why":["","It can; the transition width falls as 1 / N for any window.","The taps are real and symmetric.","They are symmetric, which is why they have linear phase."]},{"question":"A 115-tap filter must produce 48 000 samples a second on one multiplier. What is the slowest clock that works?","options":["5.52 MHz","48 kHz","110 kHz","2.76 MHz"],"answer":0,"explain":"One multiplication a clock and 115 of them a sample: 115 × 48 000 = 5.52 million a second, well under the 315 MHz the gates can run at. Folding would halve it, at the price of a pre-adder and a second read of the ring, and the gates in this chapter do not fold.","why":["","That is one multiplication a sample.","That is about two clocks a sample, far too few for this many taps.","That assumes folding, which this design does not do."]}],
  "iir": [{"question":"A mask asks for a sharp transition at a low frequency. Which costs the fewest multiplications a sample?","options":["An elliptic IIR filter in second-order sections","A Butterworth IIR filter in second-order sections","A window FIR filter","They cost the same: a mask fixes the multiplications"],"answer":0,"explain":"For equal specifications the elliptic design has the lowest order, since its ripples in both bands are spent on steepness: 20 multiplications, against 58 for the shortest folded FIR filter (2.9 times) and 93 for Butterworth (4.7 times).","why":["","Butterworth is flat in both bands, and flatness is paid for in order: 37 against 8 here.","A window FIR needs a length inversely proportional to the transition width.","The multiplications follow from the order or length that the family needs, and families differ greatly."]},{"question":"A pole asked for at radius 0.97 is held in a 5-bit coefficient word, as in step 3. What does the register hold?","options":["A pole pair exactly on the unit circle","A pole pair at radius 0.97, slightly off in angle","A double pole at z = 1","A pole pair outside the circle"],"answer":0,"explain":"a₂ = r² = 0.941 rounds to 1.0 at a step of 0.125, and a pair on the circle never decays. At 4 bits a₁ also reaches −2 and both roots are at z = 1.","why":["","Rounding a₂ to the lattice moves the radius a lot, not the angle: here the radius lands on 1.","That is the 4-bit word: a₁ rounds to −2 as well.","A section's coefficient range stops a₂ at 2 − step, and rounding never took this one beyond the circle."]},{"question":"A biquad with a₂ = 14 787 / 2¹⁴ rings on after its input has stopped, at 5 LSB. A wider accumulator is proposed. What would it change?","options":["Nothing: the accumulator is already exact, and the rounding that sustains the cycle comes after it","It would remove the cycle, since the cycle is an overflow","It would halve the cycle","It would make the cycle louder"],"answer":0,"explain":"The accumulator keeps all 29 fractional bits of every product. What feeds back is the output after rounding, and no width before the rounding can change that.","why":["","It is not an overflow: the values are 5, 0, −5, 0. Overflow is a different failure.","The accumulator has no part in setting the amplitude: the dead band ½ / (1 − a₂) does.","Its level is fixed by a₂ and the rounding, so it is not affected."]}],
  "multirate": [{"question":"A decimator by 8 uses a 64-tap filter. How many multiplications does each input sample cost, done by branches?","options":["8","64","512","1"],"answer":0,"explain":"One output in eight is computed, for 64 products, so 64 / 8 = 8 for each input sample.","why":["","That is what the direct form spends, computing outputs that are then dropped.","That multiplies where it should divide.","One multiplication an input sample would mean only 8 products an output, and this filter has 64 taps."]},{"question":"A CIC's integrators overflow constantly. Why does the output stay right?","options":["Only differences of them reach the output","The combs clamp each sum before it can do harm","The input is too small for them ever to overflow","A CIC is only right on average, over many outputs"],"answer":0,"explain":"Two's complement differences are right even across a wrap. Adding and subtracting modulo 2^w gives the true answer modulo 2^w. As long as the true output fits in w bits, the wraps on the way cancel exactly.","why":["","Nothing in it saturates, and saturating would destroy the very arithmetic that makes it work.","A running sum of anything but zero overflows sooner or later.","It is exact, bit for bit. The tests compare it with a plain FIR."]},{"question":"Why does a CIC usually have a short ordinary filter after it?","options":["It droops, and rejects well only near its nulls","It cannot lower the rate without some help","Its output has the wrong sign at the low rate","Its registers need clearing from time to time"],"answer":0,"explain":"The response is (sin(πRf) / (R sin(πf)))^N, which falls across the kept band. A filter there can flatten it and supply the sharp edge, and that filter runs at a low rate, where multiplications are few.","why":["","It does lower the rate. What it lacks is a flat band and a sharp edge.","Its gain is positive at DC, and it is fixed.","They never need clearing: the wraps cancel."]}],
  "cordic": [{"question":"Why does CORDIC use the angles atan 1, atan ½, atan ¼ and so on?","options":["Their tangents are powers of two","They add up to exactly 90°","Only those angles fit in a small ROM","They keep the vector's length at 1"],"answer":0,"explain":"A rotation has a factor of tan θ on each cross term. With tan θ = 2^−i, that multiplication is a shift, and a shift is wiring.","why":["","They add up to about 99.9°, which is why a half-turn has to handle the rest of the circle.","A ROM could hold any angle. What matters is what the angle does to the multiplications.","The length grows at every stage. That is the gain the start value pays for."]},{"question":"Why can the gain be paid in advance, by a single constant?","options":["Every stage always runs, either way","The gain is exactly 1 after 16 stages","The ROM of angles corrects it as it goes","Each stage divides the vector back down"],"answer":0,"explain":"A stage multiplies the length by √(1 + 2^−2i) whichever way it turned, since cos(−θ) = cos θ. Only if a stage could be skipped would the gain depend on the angle.","why":["","It tends to about 1.6468, and stays there.","The angles only steer. They never touch the length.","Nothing divides. Each stage lengthens, which is why x and y need headroom."]},{"question":"You need a sine to about 12 bits at one result a clock. Which do you price first?","options":["A pipelined CORDIC","An iterative CORDIC","A full-period ROM with 2^6 words","Four tree multipliers"],"answer":0,"explain":"A plain table of that accuracy costs several times more. With no interpolation it gains about a bit per address bit, and doubles its size each time. At 12 bits the pipeline is the smaller of the two, and it also gives arctangent and magnitude.","why":["","It is by far the smallest, and it takes 17 clocks a result, not one.","Sixty-four words give about 3 bits.","Multipliers still need the sine and cosine they are to multiply by."]}],
  "mac": [{"question":"Why does racc take its shift from a register and round only once, at the end?","options":["Any Q format works, and rounding each product would add noise to every tap","The accumulator has no room for a binary point","A shifter is cheaper than an adder","The clamp needs the shift to be 15"],"answer":0,"explain":"The accumulator holds products exactly. Dropping bits product by product would add a rounding error 64 times; dropping them once adds one. The register shift lets the same instruction serve Q15 data and Q13 coefficients alike.","why":["","It has no binary point at all: it is a plain integer, and the shift is what places the point.","The 41-bit shifter is about a tenth of the unit. Cheapness is not why.","The clamp is to 32 bits whatever the shift is."]},{"question":"A 64-tap FIR runs on mac with one sample per word. What stays in every tap's loop?","options":["Two loads, two pointer steps and a branch","Only the mac","A shift and a round","A call to a multiply routine"],"answer":0,"explain":"mac replaces the multiply and the add. The operands still have to come from memory, and the loop still has to count. That is why a product costs about 6 clocks and not 1.","why":["","It would be one clock a tap without the loads. The loads are most of the cost.","Those happen once per output, in racc.","That is what the instruction removed."]},{"question":"Why does the mac2 FIR need two copies of the coefficients?","options":["An even and an odd output pair the samples with the taps differently","The two multipliers need separate memories","Negative taps need their own copy","Packing loses the low taps"],"answer":0,"explain":"A data word holds samples 2w and 2w + 1. For an even output the taps against them start on an even index, for an odd output one lower. Two packed copies of the taps let the samples stay where they are.","why":["","Both multipliers read the same two registers; the memory has one port.","A sign is just a bit of the 16-bit tap.","Nothing is lost: the odd copy has one half-empty word at each end."]}],
  "dspcore": [{"question":"A 64-tap filter inner loop runs on the DSP core. What is in the loop?","options":["One mac instruction","Two loads, two pointer steps, a mac and a branch","A mac and a branch on the count","A mac and a pointer step"],"answer":0,"explain":"The pointers step as the mac reads them, and the loop unit sends the PC back with no branch. The loop is one instruction long, so a tap costs one clock.","why":["","That is the RV32 with a MAC unit. It is where the six clocks a tap came from.","There is no branch: the loop unit holds the count.","The step is part of the access: the mode in the operand does it."]},{"question":"Why does a circular window make a delay line cheaper?","options":["The newest sample overwrites the oldest and nothing moves","It needs no memory","It lets the multiplier run faster","It makes the address a constant"],"answer":0,"explain":"Shifting a delay line would cost N moves a sample. With a circular window the pointer wraps at the end, and only one word is written per sample.","why":["","The samples still have to be kept somewhere.","The multiplier does not see the window.","The address changes at every access: it steps and wraps."]},{"question":"The FFT reads its input in bit-reversed order. What does the address generator do about it?","options":["It adds the modifier with the carry running the other way","It reads the memory backwards","It stores the table of orders in the ROM","It runs the FFT in the opposite direction"],"answer":0,"explain":"Reverse the bits of the address, add the reversed modifier, reverse back. With the modifier 32 that counts 0, 32, 16, 48, … for 64 points, using an adder and wiring.","why":["","Backwards would be descending addresses, not a bit-reversed pattern.","A table of 64 orders would cost a ROM; this costs wires.","The direction of the transform is unrelated to the order the inputs are read in."]}],
  "converters": [{"question":"A 16-bit converter measures 74 dB of SNDR on a sine. What are its effective bits?","options":["About 12","About 16","About 74","About 8"],"answer":0,"explain":"(74 − 1.76) / 6.02 is 12. The other four bits are there, and what they say is noise.","why":["","That is how many bits it delivers, not how many are right.","That is the same quantity in decibels.","That would be about 50 dB."]},{"question":"A design has 1 ps of clock jitter. Which input is hurt more?","options":["A 100 MHz input at any rate","A 1 MHz input at the same rate","Either: only the sample rate counts","Neither: jitter only moves the samples"],"answer":0,"explain":"A timing error turns into a voltage error through the signal's slope, and the slope goes with frequency. A hundred times the frequency costs 40 dB.","why":["","Its slope is a hundred times smaller.","The formula has the signal's frequency in it, and no sample rate at all.","Moving a sample on a slope changes its value. That is the error."]},{"question":"What does the feedback in a sigma-delta loop do to the quantizer's error?","options":["Moves most of it above the band","Removes it altogether, given time","Lowers the total of it","Adds it to the input"],"answer":0,"explain":"The output is z⁻¹U + (1 − z⁻¹)²E. The error is all still there, and (1 − z⁻¹)² is small at low frequencies and large at high ones.","why":["","It is still there: the identity holds to the bit.","A shaped error has more total power, not less. It is just in a place a filter can reach.","That is the one thing it does not do to the band that is kept."]}],
  "adaptive": [{"question":"What does LMS need to know in advance about the signal it is filtering?","options":["Nothing: only a step size","Its autocorrelation","Its correlation with d","The impulse response it seeks"],"answer":0,"explain":"Each update uses only the current samples and the current error. The correlations are what the Wiener solution needs, and LMS averages its way to the same place without them.","why":["","The Wiener solution needs that, and LMS does not.","That too is for the Wiener solution.","If you knew it you would not need to learn."]},{"question":"A plain LMS canceller is stable, then the far end talks ten times louder and it diverges. What does that say?","options":["Its step limit depends on power","Its filter is too short for the path","The echo path has changed","It needs more bits"],"answer":0,"explain":"The limit goes as 2 / (N σ²). Ten times the amplitude is a hundred times the power, so a step that was safe no longer is. NLMS fixes this by dividing the step by the input's power.","why":["","A short filter leaves echo, and it stays stable.","Nothing here says it has, and a change would only send it learning.","Bits are what the fixed-point version wants, and this is in real numbers."]},{"question":"Why does an echo canceller stop learning when someone talks at the near end?","options":["Their voice lands in the error","Their voice raises the far end's power","The microphone turns off","It saves multiplications"],"answer":0,"explain":"Near-end speech lands in the error. It has nothing to do with the far-end signal, so the update pushes the filter away from the answer. Holding the filter still while it lasts protects what has been learned.","why":["","The far end's signal is not changed by anything said at the near end.","It stays on, because the near-end voice is what the call is for.","It does, but that is not the reason."]}],
  "speech": [{"question":"Why does μ-law beat 8 uniform bits by so much on a quiet voice, and so little on a loud one?","options":["Its steps grow with the level","It uses more bits for quiet samples","It filters out the noise","It only works on speech"],"answer":0,"explain":"A quiet voice lives in the small steps near zero, where μ-law's are finer than uniform 8-bit steps. A loud one uses the large steps, which are coarser.","why":["","Every sample takes 8 bits either way.","It is a quantizer, and filters nothing.","It would treat any signal of the same level the same way."]},{"question":"An ADPCM decoder never receives the step size. How does it know it?","options":["It updates it from each code","It reads it from a header every frame","It measures the decoded signal's level","It uses one fixed step throughout"],"answer":0,"explain":"The step index moves by the same table from the same codes on both sides, so the two stay in step for as long as no code is lost.","why":["","IMA ADPCM has no such header in its stream of codes.","That would lag, and the encoder would not know what it had measured.","The step adapts: that is the A in ADPCM."]},{"question":"What does a vocoder send for a voiced frame, beyond the filter?","options":["A pitch period and a level","The residual, sample by sample","The waveform at a lower rate","Only the filter, nothing more"],"answer":0,"explain":"The source is modelled as a pulse train at the pitch, scaled to the level. That is a few bits a frame instead of every sample.","why":["","Sending the residual is what a waveform coder does, and it costs far more.","That is resampling, and it would keep the waveform's bits.","With no source, the filter would have nothing to shape."]}],
  "music": [{"question":"An MDCT frame alone, transformed and back, has aliasing. What removes it?","options":["Adding the next frame's overlapping half","A longer transform with more coefficients","A low-pass filter after it","Quantizing more finely"],"answer":0,"explain":"The aliasing in the second half of one frame is the opposite of the aliasing in the first half of the next. Overlap-added, it cancels: time-domain aliasing cancellation.","why":["","A longer frame has the same problem at its own edges.","The aliasing is in time, and in the same band as the music.","It is there with no quantization at all."]},{"question":"Why does a masking model let a codec spend fewer bits?","options":["Noise under the mask is not heard","Masked bands are louder","The mask removes the noise","It lowers the sample rate of each band"],"answer":0,"explain":"The codec only has to keep each band's quantization noise below what nearby sounds hide. Bands far below the mask need no bits at all.","why":["","A masked band is the quiet one, near a louder one.","The noise is still there; the ear just cannot pick it out.","The rate is unchanged: only the bits per coefficient change."]},{"question":"From the same 64 kb/s budget, bits by signal give 28 dB more SNR than bits by mask. Which sounds better, by the model?","options":["Bits by mask","Bits by signal","Both the same","Neither: SNR says nothing"],"answer":0,"explain":"Bits by signal pile into the loudest bands, where noise is masked anyway, and leave quiet bands with audible noise. SNR does not see the difference.","why":["","More SNR, and more bands with noise above their mask.","They put their noise in different places, and only one hides it.","It says something, just not what the ear hears."]}],
  "sensors": [{"question":"A blue photon (450 nm) and a red one (650 nm) are both absorbed by the same pixel. How many electrons does each make?","options":["One each","More for the blue one, which has more energy","More for the red one, which goes deeper","Neither, below the band gap"],"answer":0,"explain":"Each photon above the band gap frees one electron–hole pair; the extra energy of the blue one ends as heat. Colour changes where it is absorbed, not how much charge it makes.","why":["","The surplus energy is lost as heat, not as more electrons (until far ultraviolet).","Depth changes the chance of being collected, not the count.","Both are well above 1.12 eV."]},{"question":"Why does correlated double sampling remove kTC noise?","options":["Both samples see the same reset, so its error cancels in the difference","It averages two independent resets","It filters out high frequencies on the column","It doubles the signal and halves the noise"],"answer":0,"explain":"The reset freezes a random error on the floating diffusion. The reset sample and the signal sample both carry it, and the subtraction leaves only the charge that TX moved.","why":["","Two independent resets would add their noise, not cancel it.","kTC noise is a constant offset for the whole readout, not a high frequency.","The signal is counted once; only the error cancels."]},{"question":"A pixel has a full well of 15 000 e⁻ and 3 e⁻ of read noise. In bright light it collects 10 000 e⁻. What limits its SNR?","options":["Shot noise: √10 000 = 100, far above 3","Read noise, always the largest in a CMOS pixel","Dark current, which grows with light","The full well, which it has reached"],"answer":0,"explain":"Shot noise is √N, 100 e⁻ here, against 3 e⁻ of read noise: SNR ≈ 100. Only in the dark, below about 10 e⁻, does the read noise matter.","why":["","Read noise rules only when the signal is a few electrons.","Dark current depends on time and temperature, not on light.","10 000 is below 15 000: the well is not full."]}],
  "pictures": [{"question":"A blur kernel is 15 × 15 and is a product of a row filter and a column filter. How many multiplications a sample does it need, done the cheap way?","options":["30","225","15","450"],"answer":0,"explain":"A row pass of 15 and a column pass of 15. The full kernel would be 225.","why":["","That is the kernel applied whole.","That is only one of the two passes.","That counts both passes as if each were whole."]},{"question":"Where in a JPEG encoder is information thrown away?","options":["In rounding each coefficient to its step","In the DCT, which moves the energy around","In the Huffman coding of the runs","In the zig-zag reordering of the block"],"answer":0,"explain":"The transform can be undone to rounding, and zig-zag and Huffman are exact. Only quantization loses.","why":["","Its inverse gives the block back, to the last bit of a float.","A Huffman code decodes to exactly what went in.","A reordering only changes which coefficient is sent first."]},{"question":"Why does JPEG scan the coefficients in zig-zag order?","options":["It puts the zeros together at the end","It makes the DCT cheaper to compute","It improves the PSNR","The Huffman table requires a sorted list"],"answer":0,"explain":"High frequencies are usually quantized to 0, and zig-zag goes from low to high, so the zeros come in long runs that a few codes, and one end of block, cover.","why":["","The order is chosen after the transform, and costs it nothing.","It changes nothing about what is lost.","The codes are for (run, size) pairs, in any order."]}],
  "sdr": [{"question":"The mixer multiplies each complex sample by e^(−jθ), and θ advances by the tuning word every clock. What does that do to a station at +100 kHz when the word stands for +100 kHz?","options":["Moves it to 0 Hz","Moves it to 200 kHz","Filters out everything else","Doubles its deviation"],"answer":0,"explain":"The multiplication subtracts the oscillator's frequency from every frequency in the band: 100 − 100 = 0. A station at −300 kHz moves to −400 kHz, and the filters that follow take it out.","why":["","Mixing with e^(−jθ) subtracts. A real mixer would also make the sum, which is why this one is complex.","A mixer is a multiplier and changes no amplitudes. The filters after it remove the others.","It shifts the whole spectrum; the deviation, which is a width, does not change."]},{"question":"The test tone tuned on its own frequency sounded the same from a 4-bit table to a 9-bit one, while the weak station's keying did not. What does that show about the table?","options":["The tone's tuning word puts its phase on table points, which hides the error; the weak station is off the grid and beside a loud one","The weak station uses a different table","FM audio is immune to every oscillator error","Spurs only exist in the weak station's band"],"answer":0,"explain":"A coarse table puts a spur some tens of dB below every strong signal. A tuning word with many trailing zero bits, as the test tone's has, steps the phase through a few table points exactly, so there is no staircase error to see. Tuned a little off, the same tone gets worse as the table shrinks.","why":["","There is one table, for all of them.","FM does not make a spur harmless: tuned 100 Hz off its frequency the tone's SNR depends strongly on the table.","They are in every station's band, in proportion to its neighbours."]},{"question":"Why does the CIC come before the 41-tap channel filter?","options":["It takes the rate down 4× with no multipliers, so the filter runs at a quarter","It filters more sharply than any ordinary filter","It flattens the channel before it is cut","A channel filter cannot take 11-bit words"],"answer":0,"explain":"The channel filter's price is taps × rate. Put after a ÷ 4 stage it is 41 × 240 000 a second for each of I and Q instead of four times that. The CIC droops across the channel and rejects only near its nulls; the 41 taps finish the job.","why":["","It rejects well near its nulls and droops across the band. That is why a short ordinary filter follows.","It does the opposite: it droops across the band.","A filter works on words of any width the designer gives it."]}],
  "appendix-6502": [{"question":"An NMOS gate's output sits at 0. What current flows?","options":["A steady current from VDD through the depletion load and the conducting pull-downs to GND","None once the output has settled: power is drawn only while it switches","A steady current into the gates of the stages it drives"],"answer":0,"explain":"The depletion load always conducts, and the pull-downs win only because they are stronger (ratioed logic). While the output is 0 both conduct, computing or not: a whole NMOS chip dissipated a few hundred milliwatts.","why":["","That is CMOS, where one of the two networks is always off. In NMOS the load never turns off.","A MOSFET gate is insulated: current flows into it only while its charge changes."]},{"question":"In one φ1, two sources are enabled onto the same precharged bus line: one with bit 1, one with bit 0. The line reads:","options":["0: the AND of the two bits","1: the OR of the two bits","X: two drivers in contention","Whichever bit was enabled first"],"answer":0,"explain":"A source pulls its line down only where its bit is 0; a 1 leaves the precharge alone. One 0 is enough to drain the line, so the line carries the AND.","why":["","A 1 does nothing on a precharged line: only a 0 acts, by pulling it down.","Nothing drives the line high in φ1: the precharge happened in φ2, so a pull-down meets only stored charge.","Order does not matter: a 1 leaves the charge alone and a 0 drains it, whenever it arrives."]},{"question":"Where do most of the extra transistors of our single-cycle RV32I go, compared with our 6502?","options":["Storage built from logic: the register file, the data memory and the program ROM","Decoding a harder instruction set","More instructions than the 6502's 56"],"answer":0,"explain":"90 % of the RV32I is storage, 76 % in the register file and data memory alone. The 6502 keeps three 8-bit registers and leaves memory off the chip; its registers are 10 transistors a bit against about 90 for the RV32I's register file.","why":["","Decoding is not where the transistors go: storage alone is 90 % of the RV32I.","RV32I has fewer instructions than the 6502. The gap comes from storage, width (32 bits against 8) and technology."]}],
  "appendix-doom": [{"question":"Why does Doom run on our RV32IM, which has no floating-point unit?","options":["Its geometry is 16.16 fixed point: integer multiply and divide are all it needs","The fast interpreter adds the float instructions the gates lack","Doom draws flat sprites only, with no geometry to compute"],"answer":0,"explain":"Doom was written for a 386 PC, which had no floating-point unit of its own, so its renderer works in 16.16 fixed point. The compiler targets <code>-march=rv32im</code>: integer, multiply and divide.","why":["","The interpreter has the same semantics as the instruction-set simulator, and the same image runs on the gates, which have no float unit.","Doom renders walls and floors in perspective; it computes that geometry in fixed point, with integer multiplies and divides."]},{"question":"A store goes to address <code>0xC000_0140</code>. Which memory takes it?","options":["The frame buffer","The RAM","The devices","None: the region is read only"],"answer":0,"explain":"addr[31:28] = 0xC: the frame buffer's region, from <code>0xC000_0000</code>. The memory map raises that memory's write enable and no other.","why":["","The RAM is at 0: a top nibble of 0xC is far above it.","The devices start at <code>0x8000_0000</code>, below the frame buffer's region at <code>0xC000_0000</code>.","The read-only region is the WAD at <code>0x1000_0000</code> (top nibble 1)."]},{"question":"A machine runs our Doom image at 4 MHz instead of 40. What happens?","options":["The game plays ten times slower, tic for tic the same","The game keeps real time and drops frames","The game runs at full speed: the timer counts real time"],"answer":0,"explain":"Doom paces its 35 tics a second by <code>mtime</code>, which counts clock cycles and assumes 40 MHz. At 4 MHz each tic takes ten times longer in wall time and computes the same thing.","why":["","Doom has no other clock here: <code>mtime</code> counts cycles, so the program cannot tell that it is late.","<code>mtime</code> counts clock cycles, not seconds: at 4 MHz it advances ten times slower."]}],
  "appendix-sap": [{"question":"During T1 of every instruction the lines <code>RO II CE</code> are on. What happens at the rising edge?","options":["The IR takes RAM[MAR] and the PC counts","The MAR takes the PC","RAM[MAR] takes the bus","The PC loads the bus"],"answer":0,"explain":"RO puts RAM[MAR] on the bus, II loads it into the instruction register, CE lets the 161 count. MAR still holds the address T0 put there.","why":["","That is T0: MI CO. In T1 the PC does not drive the bus.","That would need RI; RO reads the RAM onto the bus.","Loading the PC from the bus is J (a jump). CE counts without touching the bus."]},{"question":"A programmer adds an instruction <code>LDB a</code> (B ← RAM[a]). What must change in the hardware?","options":["Only the two microcode EEPROMs: T2 MI IO, T3 RO BI","A new decoder for the opcode","A wire from the RAM to B","A sixth step in the counter"],"answer":0,"explain":"Every data path it needs exists: the operand onto the bus (IO) into the MAR (MI), then RAM onto the bus (RO) into B (BI). A free opcode (9–D) gets those words at its addresses in the EEPROMs.","why":["","The EEPROMs are the decoder: the opcode is part of their address.","B already loads from the bus, and the RAM already drives it.","Two execute steps are enough; the counter already runs to T4."]},{"question":"What does SAP-1's bus do if the microcode turns on <code>AO</code> and <code>RO</code> in the same step?","options":["Two 74LS245s drive the same wires: where they disagree, an output stage shorts the supply to ground","The bus takes the OR of the two values, harmlessly","The second driver waits for the first","The bus floats"],"answer":0,"explain":"A 3-state output that is enabled drives hard. Two of them disagreeing on a wire is a short through both output stages: the value is neither, and the chips heat up. Our gate-level bus ORs them as a stand-in and raises <code>clash</code>.","why":["","That is this site's gate-level stand-in, not the real bus: the real one has no OR gate, only wires.","There is no arbitration: whatever is enabled drives at once.","A floating bus is the case with no driver at all; then the pull-downs hold it at 0."]}],
  "appendix-runner": [{"question":"The wall counter loads 28 and counts to 63, a period of 36. Why must the period divide the 72-clock line?","options":["So the counter is at the same value at the same column on every line, and the wall stands straight","So the counter never overflows","So the wall is four pixels wide","So hsync can reset it"],"answer":0,"explain":"72 = 2 × 36: after each line the counter is where it was, so each line draws the wall at the same column. Any other period would draw it sheared across the lines.","why":["","It wraps by design: the wrap is what reloads it.","The width is the decode: count ≥ 60 is four values.","Nothing resets it at a line: it only slips, once a slip frame."]},{"question":"You stand in a gate of your colour. Then the score reaches a value where the gate is narrower, and a pixel of you overlaps the wall above the gate. What decides whether you crash?","options":["One clock with YOU, WALL and FIELD high and NOT (IN GATE AND colours match)","A comparison of your row against the gate's top and bottom","A count of how many of your pixels overlap","The next frame's position, checked in vertical blanking"],"answer":0,"explain":"On the line where the beam reaches your overlapping pixel, IN GATE is 0 while YOU and WALL are 1, so crash goes high for that clock. The comparison with the gate is about the line the beam is on, and not about where you are.","why":["","There is no register holding your row to compare with: your position exists only as a phase.","One pixel is enough: the first clock of overlap sets ghost, and ghost blocks any second crash.","Nothing waits: the crash happens as the beam draws it."]},{"question":"A designer wants a third colour of gate. What is the smallest change in this hardware?","options":["A wider gate register, a second colour bit in the player, a wider comparison and another video line: new wires on several boards","A new byte in the ROM","A change to the LFSR alone","A new microinstruction"],"answer":0,"explain":"A colour is stored in the gate registers, in the player, compared in Rules, and drawn in Video. On a CPU the same rule is a few instructions; here it is a change to the boards.","why":["","There is no ROM in this machine.","The LFSR would supply the bit, but nothing could hold, compare or show it.","There is no microcode: nothing is sequenced."]}],
};
